INSERT INTO stacks (id, market_id, title, stack_type, tags, duration_minutes, published_at, metadata, authored_lesson) VALUES
($ml$873be961-dc54-592e-bbc8-6d7e61b77a59$ml$::uuid, $ml$cybersecurity$ml$, $ml$Inside the phone networks$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-6$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d6-career", "title": "Inside the phone networks", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "The attackers went after the carriers themselves.", "eyebrow": "Day 6 · Where it breaks", "headline": "By December 2024, US officials said China-linked hackers had breached nine US telecom companies.", "fullText": "The campaign, called Salt Typhoon, took customer call records and reached the private communications of a limited number of people, believed to include senior US officials. The White House said voluntary security practices were inadequate against China, and the FCC was set to take up required rules for telecom companies.", "sources": [{"url": "https://www.pbs.org/newshour/world/chinese-hacking-campaign-hit-a-9th-u-s-telecom-firm-white-house-says", "label": "PBS NewsHour, Chinese hacking campaign hit a 9th US telecom"}]}, {"kind": "microInsight", "id": "target", "eyebrow": "The target", "text": "The goal was to know who calls whom, then listen to chosen targets.", "highlight": "The FBI said most targets were involved in government or politics.", "sources": [{"url": "https://www.pbs.org/newshour/world/chinese-hacking-campaign-hit-a-9th-u-s-telecom-firm-white-house-says", "label": "PBS NewsHour, Chinese hacking campaign hit a 9th US telecom"}]}, {"kind": "microInsight", "id": "scale", "eyebrow": "The scale", "text": "At least eight US telecoms were named first, then a ninth.", "highlight": "Officials said dozens of countries were affected.", "sources": [{"url": "https://www.pbs.org/newshour/world/chinese-hacking-campaign-hit-a-9th-u-s-telecom-firm-white-house-says", "label": "PBS NewsHour, Chinese hacking campaign hit a 9th US telecom"}]}, {"kind": "info", "id": "gap", "eyebrow": "The gap", "title": "Voluntary security was not enough", "body": "Telecom security had largely been voluntary. Officials called that inadequate and pushed for required practices.", "sources": [{"url": "https://www.pbs.org/newshour/world/chinese-hacking-campaign-hit-a-9th-u-s-telecom-firm-white-house-says", "label": "PBS NewsHour, Chinese hacking campaign hit a 9th US telecom"}]}, {"kind": "multipleChoice", "id": "mc", "prompt": "What did the Salt Typhoon hackers mainly want from the telecoms?", "options": ["A large ransom paid in cryptocurrency", "Call records and targets' messages", "To shut down the national phone network"], "correctIndex": 1, "explanation": "This was espionage: who calls whom, plus the calls and texts of government targets."}, {"kind": "theCall", "id": "call", "situation": "You run security at a regional phone carrier. Officials have just published guidance on hunting these intruders.", "prompt": "What do you do first?", "options": ["Wait to see if your company is named", "Hunt for the intruders using the guidance", "Announce that your network is safe"], "consequences": ["Nine carriers were hit; waiting gives intruders more time.", "The guidance exists so carriers can find them now.", "Claiming safety before checking can backfire badly."], "correctIndex": 1, "explanation": "Assume you could be a target and look. The guidance was published for exactly that."}, {"id": "lens-career", "kind": "info", "title": "Know the telecom wake-up call", "body": "Salt Typhoon reached nine US carriers. Mentioning it shows you follow nation-state threats, not just ransomware.", "eyebrow": "For your interview", "sources": [{"url": "https://www.pbs.org/newshour/world/chinese-hacking-campaign-hit-a-9th-u-s-telecom-firm-white-house-says", "label": "PBS NewsHour, Chinese hacking campaign hit a 9th US telecom"}]}, {"id": "rule", "kind": "microInsight", "text": "In cyber, the most valuable target is often the network everyone else depends on.", "eyebrow": "The rule", "sources": [{"url": "https://www.pbs.org/newshour/world/chinese-hacking-campaign-hit-a-9th-u-s-telecom-firm-white-house-says", "label": "PBS NewsHour, Chinese hacking campaign hit a 9th US telecom"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Salt Typhoon breached nine US telecoms by December 2024, taking call records and some officials' communications. Officials called voluntary telecom security inadequate.", "sectionKey": "my_view"}]}$ml$::jsonb),
