($ml$44559286-526c-5ff1-840d-95c839cdabb1$ml$::uuid, $ml$cybersecurity$ml$, $ml$Paying hackers to find flaws first$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-8$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d8-career", "title": "Paying hackers to find flaws first", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Companies pay outsiders to break their products.", "eyebrow": "Day 8 · The money", "headline": "In 2024, Google paid $11.8 million to 660 security researchers who found flaws in its products.", "fullText": "This is a bug bounty: outside researchers report flaws privately and get paid instead of selling or publishing them. Google's top single reward that year was $110,000, and its programs have paid $65 million since 2010. Chrome alone paid $3.4 million to 137 researchers.", "sources": [{"url": "https://www.techradar.com/pro/security/google-bug-bounty-payments-hit-nearly-usd12-million-in-2024", "label": "TechRadar, Google bug bounty payments in 2024"}]}, {"kind": "microInsight", "id": "deal", "eyebrow": "The deal", "text": "Researchers report flaws privately; the company fixes them, then pays.", "highlight": "It turns potential attackers into paid testers.", "keyTerms": [{"term": "Bug bounty", "definition": "A program that pays outside researchers for privately reporting security flaws."}], "sources": [{"url": "https://www.techradar.com/pro/security/google-bug-bounty-payments-hit-nearly-usd12-million-in-2024", "label": "TechRadar, Google bug bounty payments in 2024"}]}, {"kind": "microInsight", "id": "cheap", "eyebrow": "The math", "text": "For a company Google's size, $11.8 million a year is cheap insurance.", "highlight": "The average US breach cost $10.22 million in 2025.", "sources": [{"url": "https://www.techradar.com/pro/security/google-bug-bounty-payments-hit-nearly-usd12-million-in-2024", "label": "TechRadar, Google bug bounty payments in 2024"}, {"url": "https://cyberscoop.com/ibm-cost-data-breach-2025/", "label": "CyberScoop on IBM Cost of a Data Breach 2025"}]}, {"kind": "info", "id": "scale", "eyebrow": "The track record", "title": "Bounties are now routine", "body": "Google has run reward programs since 2010 and paid $65 million in total.", "bullets": ["Its biggest single 2024 reward was $110,000."], "sources": [{"url": "https://www.techradar.com/pro/security/google-bug-bounty-payments-hit-nearly-usd12-million-in-2024", "label": "TechRadar, Google bug bounty payments in 2024"}]}, {"kind": "numberSense", "id": "ns-avg", "prompt": "Google paid $11.8 million to 660 researchers in 2024. About how much is that per researcher, in thousands of dollars?", "min": 0, "max": 60, "value": 18, "unit": "K", "explanation": "$11.8 million ÷ 660 is about $18,000 each, though a few big finds take much more."}, {"kind": "faceOff", "id": "face", "prompt": "Which is usually better for the company when a researcher finds a serious flaw?", "left": {"name": "The flaw is reported and paid for", "note": "Fixed before attackers use it"}, "right": {"name": "The flaw stays hidden", "note": "Until someone exploits it"}, "correctIndex": 0, "explanation": "Paying for a private report costs far less than a breach."}, {"id": "lens-career", "kind": "info", "title": "Bounties build a track record", "body": "Many security careers start with bug bounty finds. A credited report is proof of skill you can show.", "eyebrow": "For your interview", "sources": [{"url": "https://www.techradar.com/pro/security/google-bug-bounty-payments-hit-nearly-usd12-million-in-2024", "label": "TechRadar, Google bug bounty payments in 2024"}]}, {"id": "rule", "kind": "microInsight", "text": "In cyber, paying someone to find a flaw is cheaper than paying for the breach.", "eyebrow": "The rule", "sources": [{"url": "https://www.techradar.com/pro/security/google-bug-bounty-payments-hit-nearly-usd12-million-in-2024", "label": "TechRadar, Google bug bounty payments in 2024"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Bug bounties pay outsiders to report flaws privately. Google paid $11.8 million to 660 researchers in 2024 and $65 million since 2010.", "sectionKey": "how_money_moves"}]}$ml$::jsonb),
