($ml$d912c173-3101-5b7a-ad7b-13472915f18d$ml$::uuid, $ml$cybersecurity$ml$, $ml$The list that sets the patching clock$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-9$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d9-career", "title": "The list that sets the patching clock", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "One agency decides what is urgent.", "eyebrow": "Day 9 · The power", "headline": "Under CISA's directive BOD 22-01, US civilian agencies must fix listed flaws within two weeks.", "fullText": "CISA keeps the Known Exploited Vulnerabilities catalog. A flaw goes on it only with a CVE ID, clear remediation guidance and reliable evidence it is being exploited in the wild. Agencies get two weeks for most listed flaws and six months for those with CVE IDs from before 2021.", "sources": [{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}]}, {"kind": "microInsight", "id": "criteria", "eyebrow": "The bar", "text": "The catalog lists only flaws attackers are actually using.", "highlight": "That turns 40,000 a year into a short, urgent list.", "keyTerms": [{"term": "KEV catalog", "definition": "CISA's list of vulnerabilities with reliable evidence of exploitation in the wild."}], "sources": [{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}, {"url": "https://jerrygamblin.com/2025/01/05/2024-cve-data-review/", "label": "Jerry Gamblin, 2024 CVE data review"}]}, {"kind": "microInsight", "id": "reporting", "eyebrow": "The follow-up", "text": "Agencies must report their progress, not just promise it.", "highlight": "Status goes to a federal dashboard CISA can watch.", "sources": [{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}]}, {"kind": "info", "id": "power", "eyebrow": "Who decides", "title": "CISA sets the deadline", "body": "Once a flaw is listed, federal agencies have no choice about urgency. CISA can shorten deadlines in cases of grave risk.", "sources": [{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}]}, {"kind": "spotFake", "id": "fake", "prompt": "One of these is false. Tap it.", "statements": ["A listed flaw needs reliable evidence of exploitation.", "Agencies get two weeks for most listed flaws.", "Every published CVE goes on the catalog."], "fakeIndex": 2, "explanation": "Only flaws with a CVE ID, clear guidance and evidence of exploitation make the list."}, {"kind": "multipleChoice", "id": "mc", "prompt": "Why does the catalog help defenders more than the full CVE list?", "options": ["It covers more vulnerabilities", "It lists only flaws being used now", "It gives each flaw a higher score"], "correctIndex": 1, "explanation": "Exploitation in the wild is the signal. It shrinks a huge list to the ones that need fixing first."}, {"id": "lens-career", "kind": "info", "title": "Mention the KEV catalog", "body": "Saying you would patch KEV-listed flaws first shows you know how real teams prioritize.", "eyebrow": "For your interview", "sources": [{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}]}, {"id": "rule", "kind": "microInsight", "text": "In cyber, whoever decides what is urgent shapes where defenders spend their time.", "eyebrow": "The rule", "sources": [{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "CISA's catalog lists only flaws with evidence of exploitation, and BOD 22-01 gives US civilian agencies two weeks to fix most of them.", "sectionKey": "questions"}]}$ml$::jsonb),
