($ml$00c64978-8f57-57cd-8ab2-331af784507a$ml$::uuid, $ml$cybersecurity$ml$, $ml$Five days to exploit$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-10$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d10-career", "title": "Five days to exploit", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "The window to patch keeps shrinking.", "eyebrow": "Day 10 · The numbers", "headline": "In 2023, attackers exploited newly disclosed flaws in five days on average, down from 63.", "fullText": "Mandiant measures time-to-exploit: the days between a flaw becoming known and its first use in attacks. It averaged 63 days in 2018 and 2019, 32 days in 2021 and 2022, and five days in 2023. Of 138 exploited flaws it tracked from 2023, 97 were zero-days.", "sources": [{"url": "https://cloud.google.com/blog/topics/threat-intelligence/time-to-exploit-trends-2023?hl=en", "label": "Google Cloud (Mandiant), time-to-exploit trends 2023"}]}, {"kind": "microInsight", "id": "tte", "eyebrow": "The metric", "text": "Time-to-exploit is how long defenders have before attacks start.", "highlight": "It fell from 63 days to five in about five years.", "keyTerms": [{"term": "Time-to-exploit", "definition": "Average days between a flaw becoming known and its first use in attacks."}], "sources": [{"url": "https://cloud.google.com/blog/topics/threat-intelligence/time-to-exploit-trends-2023?hl=en", "label": "Google Cloud (Mandiant), time-to-exploit trends 2023"}]}, {"kind": "microInsight", "id": "zero", "eyebrow": "The mix", "text": "About 70% of the exploited flaws Mandiant tracked were zero-days.", "highlight": "For those, there was no patch to apply in time.", "sources": [{"url": "https://cloud.google.com/blog/topics/threat-intelligence/time-to-exploit-trends-2023?hl=en", "label": "Google Cloud (Mandiant), time-to-exploit trends 2023"}]}, {"kind": "info", "id": "outliers", "eyebrow": "Read it right", "title": "Averages hide long tails", "body": "Mandiant left out 15 outliers. With them, the 2023 average rises from five days to 47.", "sources": [{"url": "https://cloud.google.com/blog/topics/threat-intelligence/time-to-exploit-trends-2023?hl=en", "label": "Google Cloud (Mandiant), time-to-exploit trends 2023"}]}, {"kind": "numberSense", "id": "ns-tte", "prompt": "What was the average time-to-exploit in 2023, in days?", "min": 0, "max": 40, "value": 5, "unit": "days", "tolerance": 0.06, "explanation": "Five days, down from 32 in 2021 and 2022 and 63 in 2018 and 2019."}, {"kind": "multipleChoice", "id": "mc", "prompt": "What does a five-day time-to-exploit mean for a monthly patch cycle?", "options": ["It is fast enough for most flaws", "Attackers can strike weeks before it", "It no longer matters at all"], "correctIndex": 1, "explanation": "If attacks start within days, waiting up to a month leaves systems open."}, {"id": "lens-career", "kind": "info", "title": "Quote the shrinking window", "body": "Five days to exploit, down from 63. That one number explains why patch speed is a job in itself.", "eyebrow": "For your interview", "sources": [{"url": "https://cloud.google.com/blog/topics/threat-intelligence/time-to-exploit-trends-2023?hl=en", "label": "Google Cloud (Mandiant), time-to-exploit trends 2023"}]}, {"id": "rule", "kind": "microInsight", "text": "In cyber, defenders are racing a clock that keeps getting shorter.", "eyebrow": "The rule", "sources": [{"url": "https://cloud.google.com/blog/topics/threat-intelligence/time-to-exploit-trends-2023?hl=en", "label": "Google Cloud (Mandiant), time-to-exploit trends 2023"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Average time-to-exploit fell from 63 days in 2018 and 2019 to five days in 2023, and about 70% of exploited flaws were zero-days.", "sectionKey": "numbers"}]}$ml$::jsonb),
