, "id": "open-source", "eyebrow": "The root cause", "title": "Free code, thin support", "body": "Critical software is often kept up by a few volunteers. The board called for better security practices in open source.", "sources": [{"url": "https://therecord.media/first-cyber-safety-review-board-report-finds-log4j-has-become-an-endemic-vulnerability/", "label": "The Record, Log4j is an endemic vulnerability"}]}, {"kind": "multipleChoice", "id": "mc", "prompt": "Why did the board call Log4j \"endemic\"?", "options": ["It was only found in Chinese systems", "Unpatched copies will linger for years", "It could not be fixed by any patch"], "correctIndex": 1, "explanation": "A fix exists, but the library is buried in so many products that old copies will stay for a decade or more."}, {"kind": "theCall", "id": "call", "situation": "A flaw like Log4j is announced. You are not sure where the library is used in your company.", "prompt": "What do you do first?", "options": ["Patch only the systems you remember", "Find every place the library is used", "Wait for vendors to tell you"], "consequences": ["Forgotten systems stay open.", "You cannot patch what you have not found.", "Attackers will not wait for vendors."], "correctIndex": 1, "explanation": "An inventory of what software you run comes before any patch."}, {"id": "lens-invest", "kind": "info", "title": "Open source is a shared risk", "body": "One free library put countless products at risk. Tools that map software components benefit.", "eyebrow": "For investors", "sources": [{"url": "https://therecord.media/first-cyber-safety-review-board-report-finds-log4j-has-become-an-endemic-vulnerability/", "label": "The Record, Log4j is an endemic vulnerability"}]}, {"id": "rule", "kind": "microInsight", "text": "In cyber, the risk you inherit from other people's code is still your risk.", "eyebrow": "The rule", "sources": [{"url": "https://therecord.media/first-cyber-safety-review-board-report-finds-log4j-has-become-an-endemic-vulnerability/", "label": "The Record, Log4j is an endemic vulnerability"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Log4j, a free library inside countless products, had a flaw a US board called endemic in 2022. Unpatched copies may linger for a decade or more.", "sectionKey": "risk"}]}$ml$::jsonb),
