($ml$7622e79d-023a-56b0-ad15-f6c904899e7f$ml$::uuid, $ml$cybersecurity$ml$, $ml$The backdoor found by accident$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-12$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d12-career", "title": "The backdoor found by accident", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Half a second gave it away.", "eyebrow": "Day 12 · Where it breaks", "headline": "In March 2024, an engineer noticed SSH logins taking 500 milliseconds longer and found a backdoor.", "fullText": "Andres Freund traced the delay to malicious code in XZ Utils, a compression tool used in Linux. It was shipped in versions 5.6.0 and 5.6.1 and signed by an account that had contributed to the project for several years. Because those versions were mostly in early test releases of Linux, the backdoor was caught before wide use.", "sources": [{"url": "https://www.elastic.co/cn/security-labs/500ms-to-midnight", "label": "Elastic Security Labs, the xz backdoor"}]}, {"kind": "microInsight", "id": "patient", "eyebrow": "The method", "text": "The attacker spent years earning trust as a contributor.", "highlight": "Then used that trust to ship the backdoor.", "sources": [{"url": "https://www.elastic.co/cn/security-labs/500ms-to-midnight", "label": "Elastic Security Labs, the xz backdoor"}]}, {"kind": "microInsight", "id": "luck", "eyebrow": "The save", "text": "It was caught by curiosity, not by a security tool.", "highlight": "One engineer wondered why logins were half a second slow.", "sources": [{"url": "https://www.elastic.co/cn/security-labs/500ms-to-midnight", "label": "Elastic Security Labs, the xz backdoor"}]}, {"kind": "info", "id": "gap", "eyebrow": "The gap", "title": "Who checks the maintainers?", "body": "Key open-source tools often depend on a handful of volunteers. Few safeguards check who earns commit rights.", "bullets": ["It was tracked as CVE-2024-3094."], "sources": [{"url": "https://www.elastic.co/cn/security-labs/500ms-to-midnight", "label": "Elastic Security Labs, the xz backdoor"}]}, {"kind": "buildChain", "id": "chain", "prompt": "Put the xz backdoor story in order.", "steps": ["An account contributes to the project for years", "It signs code containing a backdoor", "Versions 5.6.0 and 5.6.1 ship it", "An engineer notices slow SSH logins"], "explanation": "Years of trust, then poisoned releases, caught in March 2024 by a 500 ms delay."}, {"kind": "faceOff", "id": "face", "prompt": "What caught the xz backdoor?", "left": {"name": "An automated security scanner", "note": "Built to flag malicious code"}, "right": {"name": "A curious engineer", "note": "Who noticed a 500 ms delay"}, "correctIndex": 1, "explanation": "Andres Freund spotted the slowdown and dug in."}, {"id": "lens-career", "kind": "info", "title": "Curiosity is a security skill", "body": "The xz backdoor was caught because someone asked why logins were slow. Mention it when asked what makes a good analyst.", "eyebrow": "For your interview", "sources": [{"url": "https://www.elastic.co/cn/security-labs/500ms-to-midnight", "label": "Elastic Security Labs, the xz backdoor"}]}, {"id": "rule", "kind": "microInsight", "text": "In cyber, trusted people can be the attack path, not just flawed code.", "eyebrow": "The rule", "sources": [{"url": "https://www.elastic.co/cn/security-labs/500ms-to-midnight", "label": "Elastic Security Labs, the xz backdoor"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "In March 2024, a 500 ms SSH delay exposed a backdoor planted in XZ Utils by a trusted contributor. Open-source maintainers are now a target.", "sectionKey": "my_view"}]}$ml$::jsonb),
