($ml$3ce44cc7-bf2a-5c22-8680-f787f3640045$ml$::uuid, $ml$cybersecurity$ml$, $ml$The backdoor found by accident$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-12$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:curiosity$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d12-curiosity", "title": "The backdoor found by accident", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Half a second gave it away.", "eyebrow": "Day 12 · Where it breaks", "headline": "In March 2024, an engineer noticed SSH logins taking 500 milliseconds longer and found a backdoor.", "fullText": "Andres Freund traced the delay to malicious code in XZ Utils, a compression tool used in Linux. It was shipped in versions 5.6.0 and 5.6.1 and signed by an account that had contributed to the project for several years. Because those versions were mostly in early test releases of Linux, the backdoor was caught before wide use.", "sources": [{"url": "https://www.elastic.co/cn/security-labs/500ms-to-midnight", "label": "Elastic Security Labs, the xz backdoor"}]}, {"kind": "microInsight", "id": "patient", "eyebrow": "The method", "text": "The attacker spent years earning trust as a contributor.", "highlight": "Then used that trust to ship the backdoor.", "sources": [{"url": "https://www.elastic.co/cn/security-labs/500ms-to-midnight", "label": "Elastic Security Labs, the xz backdoor"}]}, {"kind": "microInsight", "id": "luck", "eyebrow": "The save", "text": "It was caught by curiosity, not by a security tool.", "highlight": "One engineer wondered why logins were half a second slow.", "sources": [{"url": "https://www.elastic.co/cn/security-labs/500ms-to-midnight", "label": "Elastic Security Labs, the xz backdoor"}]}, {"kind": "info", "id": "gap", "eyebrow": "The gap", "title": "Who checks the maintainers?", "body": "Key open-source tools often depend on a handful of volunteers. Few safeguards check who earns commit rights.", "bullets": ["It was tracked as CVE-2024-3094."], "sources": [{"url": "https://www.elastic.co/cn/security-labs/500ms-to-midnight", "label": "Elastic Security Labs, the xz backdoor"}]}, {"kind": "buildChain", "id": "chain", "prompt": "Put the xz backdoor story in order.", "steps": ["An account contributes to the project for years", "It signs code containing a backdoor", "Versions 5.6.0 and 5.6.1 ship it", "An engineer notices slow SSH logins"], "explanation": "Years of trust, then poisoned releases, caught in March 2024 by a 500 ms delay."}, {"kind": "faceOff", "id": "face", "prompt": "What caught the xz backdoor?", "left": {"name": "An automated security scanner", "note": "Built to flag malicious code"}, "right": {"name": "A curious engineer", "note": "Who noticed a 500 ms delay"}, "correctIndex": 1, "explanation": "Andres Freund spotted the slowdown and dug in."}, {"id": "lens-curiosity", "kind": "info", "title": "Saved by half a second", "body": "A backdoor that took years to plant was found because SSH logins got 500 milliseconds slower.", "eyebrow": "Why it matters", "sources": [{"url": "https://www.elastic.co/cn/security-labs/500ms-to-midnight", "label": "Elastic Security Labs, the xz backdoor"}]}, {"id": "rule", "kind": "microInsight", "text": "In cyber, trusted people can be the attack path, not just flawed code.", "eyebrow": "The rule", "sources": [{"url": "https://www.elastic.co/cn/security-labs/500ms-to-midnight", "label": "Elastic Security Labs, the xz backdoor"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "In March 2024, a 500 ms SSH delay exposed a backdoor planted in XZ Utils by a trusted contributor. Open-source maintainers are now a target.", "sectionKey": "frontier"}]}$ml$::jsonb),
($ml$19f2b6f7-cc27-598e-bfad-c0e2a316d680$ml$::uuid, $ml$cybersecurity$ml$, $ml$Three ways to prove you are secure$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-13$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d13-career", "title": "Three ways to prove you are secure", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Same goal, three very different proofs.", "eyebrow": "Day 13 · Frameworks", "headline": "NIST CSF is a voluntary guide, ISO 27001 is a certificate, and SOC 2 is an auditor's report.", "fullText": "NIST released version 2.0 of its Cybersecurity Framework in February 2024 for all organizations, adding a Govern function to its five others. ISO/IEC 27001 sets requirements for an information security management system, and companies can choose to be certified against it. A SOC 2 is an audit by a CPA under criteria from the AICPA.", "sources": [{"url": "https://www.huntonprivacyblog.com/2024/03/04/nist-releases-cybersecurity-framework-2-0/", "label": "Hunton, NIST releases Cybersecurity Framework 2.0"}, {"url": "https://webcf.waybackmachine.org/web/20230531192221/https://www.iso.org/isoiec-27001-information-security.html", "label": "ISO, ISO/IEC 27001 information security management"}, {"url": "https://cpl.thalesgroup.com/insights/cybersecurity/what-is-soc-2-compliance", "label": "Thales, what is SOC 2 compliance"}]}, {"kind": "microInsight", "id": "csf", "eyebrow": "NIST CSF 2.0", "text": "Six functions: Govern, Identify, Protect, Detect, Respond and Recover.", "highlight": "Govern, new in 2024, covers how leaders make security decisions.", "keyTerms": [{"term": "NIST CSF", "definition": "A voluntary US framework for organizing and improving cybersecurity."}], "sources": [{"url": "https://www.huntonprivacyblog.com/2024/03/04/nist-releases-cybersecurity-framework-2-0/", "label": "Hunton, NIST releases Cybersecurity Framework 2.0"}]}, {"kind": "microInsight", "id": "iso", "eyebrow": "ISO/IEC 27001", "text": "ISO 27001 is the best-known standard for running information security as a managed system.", "highlight": "Its current edition was published in October 2022.", "keyTerms": [{"term": "ISMS", "definition": "Information security management system: the policies and processes a company uses to manage security."}], "sources": [{"url": "https://webcf.waybackmachine.org/web/20230531192221/https://www.iso.org/isoiec-27001-information-security.html", "label": "ISO, ISO/IEC 27001 information security management"}]}, {"kind": "info", "id": "soc2", "eyebrow": "SOC 2", "title": "SOC 2 is an audit report", "body": "A CPA tests a company against up to five criteria. Security is always included; the other four are optional.", "bullets": ["Type I checks the design; Type II tests how controls work over time."], "sources": [{"url": "https://cpl.thalesgroup.com/insights/cybersecurity/what-is-soc-2-compliance", "label": "Thales, what is SOC 2 compliance"}]}, {"kind": "sortSignal", "id": "sort", "prompt": "Which framework is it?", "buckets": ["NIST CSF", "ISO 27001", "SOC 2"], "items": [{"text": "Voluntary, from a US agency", "bucket": 0}, {"text": "Added a Govern function in 2024", "bucket": 0}, {"text": "Lets a company be certified", "bucket": 1}, {"text": "Audited by a CPA", "bucket": 2}, {"text": "Comes in Type I and Type II", "bucket": 2}], "explanation": "NIST CSF is voluntary guidance, ISO 27001 can be certified, and SOC 2 is a CPA audit with two types."}, {"kind": "multipleChoice", "id": "mc", "prompt": "A customer wants proof your controls worked over the past year. What should you show?", "options": ["A SOC 2 Type II report", "A SOC 2 Type I report", "A summary of NIST CSF"], "correctIndex": 0, "explanation": "Type II tests how controls operate over a period. Type I only checks their design."}, {"id": "lens-career", "kind": "info", "title": "Name the right framework", "body": "Say NIST CSF for strategy, ISO 27001 for certification, SOC 2 for customer audits. Mixing them up is a common miss.", "eyebrow": "For your interview", "sources": [{"url": "https://www.huntonprivacyblog.com/2024/03/04/nist-releases-cybersecurity-framework-2-0/", "label": "Hunton, NIST releases Cybersecurity Framework 2.0"}, {"url": "https://webcf.waybackmachine.org/web/20230531192221/https://www.iso.org/isoiec-27001-information-security.html", "label": "ISO, ISO/IEC 27001 information security management"}, {"url": "https://cpl.thalesgroup.com/insights/cybersecurity/what-is-soc-2-compliance", "label": "Thales, what is SOC 2 compliance"}]}, {"id": "rule", "kind": "microInsight", "text": "In security, a framework is how you prove to others that you are in control.", "eyebrow": "The rule", "sources": [{"url": "https://www.huntonprivacyblog.com/2024/03/04/nist-releases-cybersecurity-framework-2-0/", "label": "Hunton, NIST releases Cybersecurity Framework 2.0"}, {"url": "https://cpl.thalesgroup.com/insights/cybersecurity/what-is-soc-2-compliance", "label": "Thales, what is SOC 2 compliance"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "NIST CSF 2.0 is voluntary guidance with six functions, ISO 27001 can be certified, and SOC 2 is a CPA audit, with Type II testing controls over time.", "sectionKey": "players"}]}$ml$::jsonb),
