($ml$1eb2452f-ea29-53ca-adc7-0c32e06907b0$ml$::uuid, $ml$cybersecurity$ml$, $ml$The gatekeeper of federal cloud$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-15$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d15-career", "title": "The gatekeeper of federal cloud", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "One program decides which clouds agencies can use.", "eyebrow": "Day 15 · The power", "headline": "In March 2026, the FedRAMP Marketplace listed 502 authorized cloud services, with 75 more in progress.", "fullText": "FedRAMP, run by the General Services Administration, gives agencies one standard way to assess, authorize and monitor the security of cloud products. In March 2025 it launched FedRAMP 20x, a revamp built on automation to speed approvals, with the goal of growing to thousands of services.", "sources": [{"url": "https://www.meritalk.com/articles/fedramp-hits-500-authorized-cloud-services/", "label": "MeriTalk, FedRAMP hits 500 authorized cloud services"}]}, {"kind": "microInsight", "id": "gate", "eyebrow": "The gate", "text": "Agencies rely on FedRAMP's standard to judge cloud security.", "highlight": "The program sets one bar for the whole government.", "keyTerms": [{"term": "FedRAMP", "definition": "The US government program that assesses and authorizes cloud products for federal use."}], "sources": [{"url": "https://www.meritalk.com/articles/fedramp-hits-500-authorized-cloud-services/", "label": "MeriTalk, FedRAMP hits 500 authorized cloud services"}]}, {"kind": "microInsight", "id": "reuse", "eyebrow": "The shortcut", "text": "One shared standard replaces each agency doing its own review.", "highlight": "That is the point of a government-wide approach.", "sources": [{"url": "https://www.meritalk.com/articles/fedramp-hits-500-authorized-cloud-services/", "label": "MeriTalk, FedRAMP hits 500 authorized cloud services"}]}, {"kind": "info", "id": "20x", "eyebrow": "The change", "title": "FedRAMP 20x wants speed", "body": "Launched in March 2025, 20x leans on automation so approvals take less time.", "bullets": ["The aim: thousands of authorized services within a few years."], "sources": [{"url": "https://www.meritalk.com/articles/fedramp-hits-500-authorized-cloud-services/", "label": "MeriTalk, FedRAMP hits 500 authorized cloud services"}]}, {"kind": "faceOff", "id": "face", "prompt": "Who holds more power in selling cloud software to US agencies?", "left": {"name": "A cloud startup", "note": "Wants federal customers"}, "right": {"name": "FedRAMP", "note": "Decides who is authorized"}, "correctIndex": 1, "explanation": "FedRAMP sets the bar agencies rely on. The startup has to clear it."}, {"kind": "multipleChoice", "id": "mc", "prompt": "What is FedRAMP 20x trying to change?", "options": ["Ban foreign cloud providers", "Speed approvals with automation", "Raise the price of authorization"], "correctIndex": 1, "explanation": "It relies on automation to approve more services, faster."}, {"id": "lens-career", "kind": "info", "title": "Know FedRAMP", "body": "Government cloud work runs through FedRAMP. Knowing how authorization works is a hireable skill.", "eyebrow": "For your interview", "sources": [{"url": "https://www.meritalk.com/articles/fedramp-hits-500-authorized-cloud-services/", "label": "MeriTalk, FedRAMP hits 500 authorized cloud services"}]}, {"id": "rule", "kind": "microInsight", "text": "In government cyber, whoever runs the approval list controls the market.", "eyebrow": "The rule", "sources": [{"url": "https://www.meritalk.com/articles/fedramp-hits-500-authorized-cloud-services/", "label": "MeriTalk, FedRAMP hits 500 authorized cloud services"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "FedRAMP sets one security bar for cloud products used by US agencies. It listed 502 authorized services in March 2026, and 20x aims to speed approvals.", "sectionKey": "questions"}]}$ml$::jsonb),
