($ml$5eab9818-c8a3-5922-a1cd-b719e2d8e6b9$ml$::uuid, $ml$cybersecurity$ml$, $ml$110 controls to keep defense work$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-16$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d16-career", "title": "110 controls to keep defense work", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "No controls, no contract.", "eyebrow": "Day 16 · The numbers", "headline": "Defense contractors handling controlled unclassified information must meet 110 security requirements under CMMC.", "fullText": "The Pentagon published its final CMMC rule in September 2025. Level 1 has 15 requirements, Level 2 has 110 and Level 3 adds 24 more. Requirements phase in from November 2025 and apply to all relevant contracts from November 10, 2028. DoD estimates more than 337,000 contractors and subcontractors are affected.", "sources": [{"url": "https://www.faegredrinker.com/en/insights/publications/2025/9/department-of-defense-publishes-final-rule-to-implement-and-enforce-cybersecurity-standards-for-contractors", "label": "Faegre Drinker, DoD final CMMC rule"}]}, {"kind": "microInsight", "id": "levels", "eyebrow": "The levels", "text": "Level 1: 15 requirements. Level 2: 110. Level 3: 24 more on top.", "highlight": "The level depends on how sensitive the data is.", "keyTerms": [{"term": "CMMC", "definition": "Cybersecurity Maturity Model Certification, the Pentagon's security rule for contractors."}], "sources": [{"url": "https://www.faegredrinker.com/en/insights/publications/2025/9/department-of-defense-publishes-final-rule-to-implement-and-enforce-cybersecurity-standards-for-contractors", "label": "Faegre Drinker, DoD final CMMC rule"}]}, {"kind": "microInsight", "id": "small", "eyebrow": "Who it hits", "text": "Nearly 230,000 small businesses are among those affected.", "highlight": "Small firms face the same rules as large ones.", "sources": [{"url": "https://www.faegredrinker.com/en/insights/publications/2025/9/department-of-defense-publishes-final-rule-to-implement-and-enforce-cybersecurity-standards-for-contractors", "label": "Faegre Drinker, DoD final CMMC rule"}]}, {"kind": "info", "id": "phase", "eyebrow": "The timeline", "title": "Phased in over three years", "body": "From November 2025, program offices add requirements where needed. From November 10, 2028, they apply to all relevant contracts.", "sources": [{"url": "https://www.faegredrinker.com/en/insights/publications/2025/9/department-of-defense-publishes-final-rule-to-implement-and-enforce-cybersecurity-standards-for-contractors", "label": "Faegre Drinker, DoD final CMMC rule"}]}, {"kind": "numberSense", "id": "ns-l2", "prompt": "How many security requirements does CMMC Level 2 include?", "min": 0, "max": 300, "value": 110, "unit": "requirements", "explanation": "110, based on NIST SP 800-171. Level 1 has 15."}, {"kind": "spotFake", "id": "fake", "prompt": "One of these is false. Tap it.", "statements": ["CMMC Level 1 has 15 requirements.", "CMMC only affects a few hundred companies.", "Full CMMC rollout comes in November 2028."], "fakeIndex": 1, "explanation": "DoD estimates more than 337,000 contractors and subcontractors are affected."}, {"id": "lens-career", "kind": "info", "title": "CMMC skills are in demand", "body": "Over 337,000 companies need help meeting CMMC. Assessors and consultants who know the 110 requirements are needed.", "eyebrow": "For your interview", "sources": [{"url": "https://www.faegredrinker.com/en/insights/publications/2025/9/department-of-defense-publishes-final-rule-to-implement-and-enforce-cybersecurity-standards-for-contractors", "label": "Faegre Drinker, DoD final CMMC rule"}]}, {"id": "rule", "kind": "microInsight", "text": "In defense contracting, security is now a condition of getting paid.", "eyebrow": "The rule", "sources": [{"url": "https://www.faegredrinker.com/en/insights/publications/2025/9/department-of-defense-publishes-final-rule-to-implement-and-enforce-cybersecurity-standards-for-contractors", "label": "Faegre Drinker, DoD final CMMC rule"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "CMMC Level 2 requires 110 security controls for contractors handling sensitive defense data. More than 337,000 companies are affected, with full rollout by November 2028.", "sectionKey": "numbers"}]}$ml$::jsonb),
