($ml$9fd05b5c-e974-5046-9cff-3c16ff1f40ea$ml$::uuid, $ml$cybersecurity$ml$, $ml$Europe's 24-hour rule$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-17$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d17-career", "title": "Europe's 24-hour rule", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Report fast or pay up.", "eyebrow": "Day 17 · The rule", "headline": "Since October 2024, companies under the EU's NIS2 rules must send an early warning within 24 hours of a significant incident.", "fullText": "A fuller notification follows within 48 hours of that warning, and a final report within a month. Essential entities face fines of up to €10 million or 2% of worldwide annual turnover, whichever is greater. Important entities face up to €7 million or 1.4%.", "sources": [{"url": "https://wsgr.com/en/insights/nis2-preparing-for-eus-new-cybersecurity-rules.html", "label": "Wilson Sonsini, preparing for the EU's NIS2 rules"}]}, {"kind": "microInsight", "id": "clock", "eyebrow": "The clock", "text": "24 hours for an early warning, 48 more for the notification.", "highlight": "Then one month for a final report with the root cause.", "keyTerms": [{"term": "NIS2", "definition": "The EU's 2022 directive setting cybersecurity and incident-reporting rules for key sectors."}], "sources": [{"url": "https://wsgr.com/en/insights/nis2-preparing-for-eus-new-cybersecurity-rules.html", "label": "Wilson Sonsini, preparing for the EU's NIS2 rules"}]}, {"kind": "microInsight", "id": "fines", "eyebrow": "The stick", "text": "Fines scale with company size: up to 2% of worldwide turnover.", "highlight": "For a big company, that can far exceed €10 million.", "sources": [{"url": "https://wsgr.com/en/insights/nis2-preparing-for-eus-new-cybersecurity-rules.html", "label": "Wilson Sonsini, preparing for the EU's NIS2 rules"}]}, {"kind": "info", "id": "scope", "eyebrow": "Who it covers", "title": "Far more than before", "body": "NIS2 widened the scope well beyond the first NIS rules, including cloud and data center providers.", "sources": [{"url": "https://wsgr.com/en/insights/nis2-preparing-for-eus-new-cybersecurity-rules.html", "label": "Wilson Sonsini, preparing for the EU's NIS2 rules"}]}, {"kind": "multipleChoice", "id": "mc", "prompt": "An essential entity has €2 billion in worldwide turnover. What is its maximum NIS2 fine?", "options": ["€10 million", "€40 million", "€2 million"], "correctIndex": 1, "explanation": "2% of €2 billion is €40 million, which is greater than €10 million."}, {"kind": "theCall", "id": "call", "situation": "Your EU cloud company finds a significant intrusion at 9 a.m. The facts are still unclear.", "prompt": "What do you do about reporting?", "options": ["Warn regulators within 24 hours", "Wait until you know everything", "Report only if data was stolen"], "consequences": ["The rule expects a warning before you have all the facts.", "Waiting can miss the 24-hour deadline.", "NIS2 covers significant incidents, not only data theft."], "correctIndex": 0, "explanation": "The early warning is designed to come fast, with details to follow."}, {"id": "lens-career", "kind": "info", "title": "Know the reporting clocks", "body": "Know the clocks: 24 hours for NIS2, four business days for the SEC, 72 hours for GDPR. It makes you useful in an incident.", "eyebrow": "For your interview", "sources": [{"url": "https://wsgr.com/en/insights/nis2-preparing-for-eus-new-cybersecurity-rules.html", "label": "Wilson Sonsini, preparing for the EU's NIS2 rules"}, {"url": "https://sec.gov/news/press-release/2023-139", "label": "SEC press release 2023-139"}, {"url": "https://gdpr-text.com/read/article-33/", "label": "GDPR Article 33"}]}, {"id": "rule", "kind": "microInsight", "text": "In cyber regulation, the reporting clock starts before you know the full story.", "eyebrow": "The rule", "sources": [{"url": "https://wsgr.com/en/insights/nis2-preparing-for-eus-new-cybersecurity-rules.html", "label": "Wilson Sonsini, preparing for the EU's NIS2 rules"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "NIS2 requires an early warning within 24 hours of a significant incident. Essential entities face fines of up to €10 million or 2% of worldwide turnover.", "sectionKey": "risk"}]}$ml$::jsonb),
