($ml$ae42e01a-fab0-54ed-8aae-504e4938d79d$ml$::uuid, $ml$cybersecurity$ml$, $ml$When the security chief was sued$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-18$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d18-career", "title": "When the security chief was sued", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Can a CISO be personally liable?", "eyebrow": "Day 18 · Where it breaks", "headline": "In October 2023, the SEC sued SolarWinds and its security chief, Tim Brown, for misleading investors.", "fullText": "The SEC said they hid cybersecurity weaknesses from the 2018 IPO until the Russian-linked Sunburst hack came to light in December 2020. In July 2024, a judge dismissed most of the claims. In November 2025, the SEC said it would drop the case. Security leaders had warned it would push people out of CISO jobs.", "sources": [{"url": "https://www.nextgov.com/cybersecurity/2025/11/sec-drop-high-profile-solarwinds-hack-lawsuit/409684/", "label": "Nextgov, SEC to drop SolarWinds lawsuit"}]}, {"kind": "microInsight", "id": "charge", "eyebrow": "The charge", "text": "The claim: public security statements did not match reality.", "highlight": "Only claims about the pre-hack Security Statement survived the 2024 ruling.", "sources": [{"url": "https://www.nextgov.com/cybersecurity/2025/11/sec-drop-high-profile-solarwinds-hack-lawsuit/409684/", "label": "Nextgov, SEC to drop SolarWinds lawsuit"}]}, {"kind": "microInsight", "id": "pushback", "eyebrow": "The pushback", "text": "Dozens of security leaders opposed the case in 2024.", "highlight": "They argued it would hurt security and CISO retention.", "sources": [{"url": "https://www.nextgov.com/cybersecurity/2025/11/sec-drop-high-profile-solarwinds-hack-lawsuit/409684/", "label": "Nextgov, SEC to drop SolarWinds lawsuit"}]}, {"kind": "info", "id": "open", "eyebrow": "The open question", "title": "The line is still unclear", "body": "The case ended without a ruling on how far a security chief is personally responsible for public claims.", "sources": [{"url": "https://www.nextgov.com/cybersecurity/2025/11/sec-drop-high-profile-solarwinds-hack-lawsuit/409684/", "label": "Nextgov, SEC to drop SolarWinds lawsuit"}]}, {"kind": "buildChain", "id": "chain", "prompt": "Put the SolarWinds case in order.", "steps": ["SolarWinds goes public", "The Sunburst hack comes to light", "The SEC sues SolarWinds and its CISO", "A judge dismisses most claims", "The SEC says it will drop the case"], "explanation": "2018 IPO, December 2020 hack, October 2023 suit, July 2024 ruling, November 2025 dismissal."}, {"kind": "multipleChoice", "id": "mc", "prompt": "What did the SolarWinds case put on the line for security leaders?", "options": ["Their personal liability for claims", "Their right to use the NIST framework", "Their salary limits under SEC rules"], "correctIndex": 0, "explanation": "The SEC named the CISO himself, raising the question of personal liability."}, {"id": "lens-career", "kind": "info", "title": "Words in public filings matter", "body": "The SEC pursued a CISO over security statements. Leaders now check public security claims against reality.", "eyebrow": "For your interview", "sources": [{"url": "https://www.nextgov.com/cybersecurity/2025/11/sec-drop-high-profile-solarwinds-hack-lawsuit/409684/", "label": "Nextgov, SEC to drop SolarWinds lawsuit"}]}, {"id": "rule", "kind": "microInsight", "text": "In cyber, what you say about your security can become a legal risk.", "eyebrow": "The rule", "sources": [{"url": "https://www.nextgov.com/cybersecurity/2025/11/sec-drop-high-profile-solarwinds-hack-lawsuit/409684/", "label": "Nextgov, SEC to drop SolarWinds lawsuit"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "The SEC sued SolarWinds and its CISO in 2023 over security statements, then dropped the case in 2025. How far security leaders are personally liable remains unsettled.", "sectionKey": "my_view"}]}$ml$::jsonb),
