($ml$37efa5bd-9d12-582c-8948-0d91a93081cd$ml$::uuid, $ml$cybersecurity$ml$, $ml$Who you are versus what you can do$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-19$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d19-career", "title": "Who you are versus what you can do", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Attackers log in more than they break in.", "eyebrow": "Day 19 · Identity", "headline": "Credential abuse was the top way into breaches in Verizon's 2025 report, at 22%.", "fullText": "Exploited software flaws were close behind at 20%. Identity and access management decides two things: authentication, proving who you are, and authorization, deciding what you may do once you are in. When attackers steal a login, both checks can wave them through.", "sources": [{"url": "https://www.verizon.com/about/news/2025%2Ddata%2Dbreach%2Dinvestigations%2Dreport", "label": "Verizon, 2025 Data Breach Investigations Report"}]}, {"kind": "microInsight", "id": "authn", "eyebrow": "Step 1", "text": "Authentication proves who you are: a password, a code, a fingerprint.", "highlight": "Multifactor authentication asks for two or more of these.", "keyTerms": [{"term": "MFA", "definition": "Multifactor authentication: proving identity with two or more different kinds of evidence."}], "sources": [{"url": "https://www.verizon.com/about/news/2025%2Ddata%2Dbreach%2Dinvestigations%2Dreport", "label": "Verizon, 2025 Data Breach Investigations Report"}]}, {"kind": "microInsight", "id": "authz", "eyebrow": "Step 2", "text": "Authorization decides what you can reach once you are in.", "highlight": "Giving each account only what it needs limits the damage.", "keyTerms": [{"term": "Least privilege", "definition": "Giving each user or system only the access it needs."}], "sources": [{"url": "https://www.verizon.com/about/news/2025%2Ddata%2Dbreach%2Dinvestigations%2Dreport", "label": "Verizon, 2025 Data Breach Investigations Report"}]}, {"kind": "info", "id": "why", "eyebrow": "Why it matters", "title": "Stolen logins look legitimate", "body": "An attacker with real credentials can look like a normal user. That is why identity is now a core security layer.", "sources": [{"url": "https://www.verizon.com/about/news/2025%2Ddata%2Dbreach%2Dinvestigations%2Dreport", "label": "Verizon, 2025 Data Breach Investigations Report"}]}, {"kind": "sortSignal", "id": "sort", "prompt": "Authentication or authorization?", "buckets": ["Authentication", "Authorization"], "items": [{"text": "Entering a one-time code", "bucket": 0}, {"text": "Scanning a fingerprint", "bucket": 0}, {"text": "Only HR can open salary files", "bucket": 1}, {"text": "Interns cannot change settings", "bucket": 1}], "explanation": "Authentication checks who you are. Authorization checks what you may do."}, {"kind": "multipleChoice", "id": "mc", "prompt": "What was the top way into breaches in Verizon's 2025 report?", "options": ["Exploiting software flaws", "Abusing stolen credentials", "Breaking into data centers"], "correctIndex": 1, "explanation": "Credential abuse led at 22%, just ahead of exploited flaws at 20%."}, {"id": "lens-career", "kind": "info", "title": "Separate the two checks", "body": "Explain authentication versus authorization clearly. It is a staple interview question in security.", "eyebrow": "For your interview", "sources": [{"url": "https://www.verizon.com/about/news/2025%2Ddata%2Dbreach%2Dinvestigations%2Dreport", "label": "Verizon, 2025 Data Breach Investigations Report"}]}, {"id": "rule", "kind": "microInsight", "text": "In cyber, identity is the new perimeter: protect the login and you protect the door.", "eyebrow": "The rule", "sources": [{"url": "https://www.verizon.com/about/news/2025%2Ddata%2Dbreach%2Dinvestigations%2Dreport", "label": "Verizon, 2025 Data Breach Investigations Report"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Authentication proves who you are; authorization decides what you can do. Credential abuse was the top way into breaches in 2025, at 22%.", "sectionKey": "players"}]}$ml$::jsonb),
