($ml$56a35fce-c1f0-5f4b-aaf1-5dc3e1ddffeb$ml$::uuid, $ml$cybersecurity$ml$, $ml$A $25 billion bet on identity$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-20$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d20-career", "title": "A $25 billion bet on identity", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Big security buyers want the keys.", "eyebrow": "Day 20 · The money", "headline": "In July 2025, Palo Alto Networks agreed to buy CyberArk, an identity security company, for about $25 billion.", "fullText": "CyberArk protects privileged accounts, the logins with the most power inside a company. Palo Alto offered $45 in cash plus 2.2005 of its own shares for each CyberArk share, a 26% premium. Its CEO pointed to AI and an explosion of machine identities as reasons for the deal.", "sources": [{"url": "https://www.intelligentcio.com/north-america/2025/07/30/palo-alto-networks-to-acquire-cyberark-in-25-billion-deal-to-expand-identity-security-and-ai-protection/", "label": "Intelligent CIO, Palo Alto Networks to acquire CyberArk"}]}, {"kind": "microInsight", "id": "privileged", "eyebrow": "What it protects", "text": "Privileged accounts can change systems, read everything or turn defenses off.", "highlight": "They are what attackers want most once inside.", "keyTerms": [{"term": "Privileged account", "definition": "An account with extra powers, such as an administrator login."}], "sources": [{"url": "https://www.intelligentcio.com/north-america/2025/07/30/palo-alto-networks-to-acquire-cyberark-in-25-billion-deal-to-expand-identity-security-and-ai-protection/", "label": "Intelligent CIO, Palo Alto Networks to acquire CyberArk"}]}, {"kind": "microInsight", "id": "machines", "eyebrow": "Why now", "text": "Not every identity is a person anymore.", "highlight": "Software, machines and AI agents all log in too.", "sources": [{"url": "https://www.intelligentcio.com/north-america/2025/07/30/palo-alto-networks-to-acquire-cyberark-in-25-billion-deal-to-expand-identity-security-and-ai-protection/", "label": "Intelligent CIO, Palo Alto Networks to acquire CyberArk"}]}, {"kind": "info", "id": "platform", "eyebrow": "The strategy", "title": "Identity becomes a core pillar", "body": "Palo Alto said the deal makes identity security a core part of its platform, alongside network and cloud security.", "sources": [{"url": "https://www.intelligentcio.com/north-america/2025/07/30/palo-alto-networks-to-acquire-cyberark-in-25-billion-deal-to-expand-identity-security-and-ai-protection/", "label": "Intelligent CIO, Palo Alto Networks to acquire CyberArk"}]}, {"kind": "numberSense", "id": "ns-deal", "prompt": "About how many billions of dollars did Palo Alto Networks agree to pay for CyberArk?", "min": 0, "max": 60, "value": 25, "unit": "B", "explanation": "About $25 billion, in cash and stock."}, {"kind": "theCall", "id": "call", "situation": "You lead security at a mid-size company. Hundreds of software bots now log in to your systems every day.", "prompt": "What do you do about them?", "options": ["Treat bots as trusted by default", "Manage bot logins like privileged users", "Share one admin password among them"], "consequences": ["Trusted bots become an easy way in.", "Machine identities get the same control as powerful human ones.", "One leaked password would open every bot."], "correctIndex": 1, "explanation": "Machine identities can be as powerful as admins, so they need the same controls."}, {"id": "lens-career", "kind": "info", "title": "Identity is a growth area", "body": "A $25 billion deal signals where security spending is going. Identity skills travel well.", "eyebrow": "For your interview", "sources": [{"url": "https://www.intelligentcio.com/north-america/2025/07/30/palo-alto-networks-to-acquire-cyberark-in-25-billion-deal-to-expand-identity-security-and-ai-protecti