($ml$ccf689b1-b88a-5d2a-916d-fc5bdaa9ae14$ml$::uuid, $ml$cybersecurity$ml$, $ml$The help desk holds the keys$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-21$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d21-career", "title": "The help desk holds the keys", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "A phone call, not malware.", "eyebrow": "Day 21 · The power", "headline": "In September 2023, a cyberattack disrupted MGM Resorts for about 10 days and cost it about $100 million.", "fullText": "MGM's filing put the hit to its adjusted property earnings at about $100 million, plus under $10 million in one-time costs. MGM never named the way in. The attackers, linked to the group known as Scattered Spider, claimed they found an employee online and called the IT help desk posing as them.", "sources": [{"url": "https://www.adaptivesecurity.com/blog/mgm-ransomware-attack", "label": "Adaptive Security, the MGM attack, citing MGM filings"}]}, {"kind": "microInsight", "id": "reset", "eyebrow": "The weak point", "text": "Whoever can reset a password holds power over every account.", "highlight": "Help desks exist to say yes to stressed callers.", "sources": [{"url": "https://www.adaptivesecurity.com/blog/mgm-ransomware-attack", "label": "Adaptive Security, the MGM attack, citing MGM filings"}]}, {"kind": "microInsight", "id": "claim", "eyebrow": "The claim", "text": "The attackers said the call took about 10 minutes.", "highlight": "That account has not been confirmed by investigators.", "sources": [{"url": "https://www.adaptivesecurity.com/blog/mgm-ransomware-attack", "label": "Adaptive Security, the MGM attack, citing MGM filings"}]}, {"kind": "info", "id": "group", "eyebrow": "The attackers", "title": "English-speaking social engineers", "body": "Microsoft describes Scattered Spider as financially motivated and native English-speaking, which makes their calls convincing.", "sources": [{"url": "https://www.adaptivesecurity.com/blog/mgm-ransomware-attack", "label": "Adaptive Security, the MGM attack, citing MGM filings"}]}, {"kind": "faceOff", "id": "face", "prompt": "Who holds more power over an employee's account?", "left": {"name": "The help desk", "note": "Can reset passwords and MFA"}, "right": {"name": "The firewall", "note": "Filters network traffic"}, "correctIndex": 0, "explanation": "A reset hands over the account. No firewall stops a legitimate login."}, {"kind": "multipleChoice", "id": "mc", "prompt": "What cut the MGM attackers' path short at other firms?", "options": ["A longer password policy", "Verifying callers before any reset", "A faster internet connection"], "correctIndex": 1, "explanation": "If the help desk verifies identity properly, a convincing voice is not enough."}, {"id": "lens-career", "kind": "info", "title": "Process is security", "body": "The MGM case shows a help desk script can matter more than any tool. Mention caller verification.", "eyebrow": "For your interview", "sources": [{"url": "https://www.adaptivesecurity.com/blog/mgm-ransomware-attack", "label": "Adaptive Security, the MGM attack, citing MGM filings"}]}, {"id": "rule", "kind": "microInsight", "text": "In cyber, whoever can reset access holds the real power.", "eyebrow": "The rule", "sources": [{"url": "https://www.adaptivesecurity.com/blog/mgm-ransomware-attack", "label": "Adaptive Security, the MGM attack, citing MGM filings"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "The 2023 MGM attack cost about $100 million. Attackers claimed a call to the IT help desk got them in, showing the power of whoever can reset access.", "sectionKey": "questions"}]}$ml$::jsonb),
