($ml$d109a838-3236-5193-9aae-461c277ab114$ml$::uuid, $ml$cybersecurity$ml$, $ml$99.22%$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-22$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:curiosity$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d22-curiosity", "title": "99.22%", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "One setting, almost all the risk.", "eyebrow": "Day 22 · The numbers", "headline": "Microsoft researchers found MFA reduces the risk of account compromise by 99.22%.", "fullText": "They studied a large set of Microsoft Azure Active Directory users who showed suspicious activity. Even for accounts whose passwords had already leaked, MFA cut the risk of compromise by 98.56%. Few security controls move a number that far.", "sources": [{"url": "https://arxiv.org/abs/2305.00945", "label": "Microsoft researchers, how effective is MFA"}]}, {"kind": "microInsight", "id": "leaked", "eyebrow": "Even after a leak", "text": "A leaked password alone was usually not enough with MFA on.", "highlight": "Risk fell by 98.56% for those accounts.", "sources": [{"url": "https://arxiv.org/abs/2305.00945", "label": "Microsoft researchers, how effective is MFA"}]}, {"kind": "microInsight", "id": "cost", "eyebrow": "The trade", "text": "MFA adds a few seconds per login.", "highlight": "In exchange it removes almost all account takeover risk.", "sources": [{"url": "https://arxiv.org/abs/2305.00945", "label": "Microsoft researchers, how effective is MFA"}]}, {"kind": "info", "id": "not-all", "eyebrow": "Read it right", "title": "Not all MFA is equal", "body": "Codes and push prompts can still be phished or approved by mistake. Stronger forms resist that.", "sources": [{"url": "https://arxiv.org/abs/2305.00945", "label": "Microsoft researchers, how effective is MFA"}, {"url": "https://www.whitehouse.gov/wp-content/uploads/2022/01/M-22-09.pdf", "label": "OMB memo M-22-09, federal zero trust strategy"}]}, {"kind": "numberSense", "id": "ns-mfa", "prompt": "By about what percent did MFA cut the risk of account compromise overall?", "min": 50, "max": 100, "value": 99, "unit": "%", "tolerance": 0.04, "explanation": "99.22% overall, and 98.56% even for accounts with leaked passwords."}, {"kind": "spotFake", "id": "fake", "prompt": "One of these is false. Tap it.", "statements": ["MFA cut compromise risk by 99.22% overall.", "MFA stopped working once a password leaked.", "The study used Azure Active Directory data."], "fakeIndex": 1, "explanation": "Even with leaked passwords, MFA cut risk by 98.56%."}, {"id": "lens-curiosity", "kind": "info", "title": "A second step, 99% safer", "body": "Turning on a second login step blocked about 99 of every 100 account compromises in one study.", "eyebrow": "Why it matters", "sources": [{"url": "https://arxiv.org/abs/2305.00945", "label": "Microsoft researchers, how effective is MFA"}]}, {"id": "rule", "kind": "microInsight", "text": "In cyber, the cheapest controls are often the ones that matter most.", "eyebrow": "The rule", "sources": [{"url": "https://arxiv.org/abs/2305.00945", "label": "Microsoft researchers, how effective is MFA"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Microsoft researchers found MFA cuts the risk of account compromise by 99.22%, and by 98.56% even when passwords have leaked.", "sectionKey": "numbers"}]}$ml$::jsonb),
($ml$5100f01b-5411-5e5c-a27c-d10551ebd424$ml$::uuid, $ml$cybersecurity$ml$, $ml$The memo that retired weak MFA$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-23$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d23-career", "title": "The memo that retired weak MFA", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Codes and push prompts were not enough.", "eyebrow": "Day 23 · The rule", "headline": "A January 2022 White House memo required phishing-resistant MFA for federal staff by the end of fiscal 2024.", "fullText": "Memo M-22-09 told agencies to stop supporting login methods that fail to resist phishing, including SMS or voice codes, one-time codes and push notifications, for routine access. It also ordered them to drop password rules requiring special characters and regular rotation.", "sources": [{"url": "https://www.whitehouse.gov/wp-content/uploads/2022/01/M-22-09.pdf", "label": "OMB memo M-22-09, federal zero trust strategy"}]}, {"kind": "microInsight", "id": "phishable", "eyebrow": "The problem", "text": "A code can be typed into a fake site as easily as a real one.", "highlight": "Phishing-resistant methods check the site, not just the person.", "keyTerms": [{"term": "Phishing-resistant MFA", "definition": "Login methods, such as security keys, that a fake website cannot trick or replay."}], "sources": [{"url": "https://www.whitehouse.gov/wp-content/uploads/2022/01/M-22-09.pdf", "label": "OMB memo M-22-09, federal zero trust strategy"}]}, {"kind": "microInsight", "id": "passwords", "eyebrow": "The surprise", "text": "The memo dropped forced password changes and special-character rules.", "highlight": "Agencies had one year to remove them.", "sources": [{"url": "https://www.whitehouse.gov/wp-content/uploads/2022/01/M-22-09.pdf", "label": "OMB memo M-22-09, federal zero trust strategy"}]}, {"kind": "info", "id": "who", "eyebrow": "Who it covers", "title": "Staff, contractors and partners", "body": "Phishing-resistant MFA is required for agency staff, contractors and partners using enterprise-managed identities.", "sources": [{"url": "https://www.whitehouse.gov/wp-content/uploads/2022/01/M-22-09.pdf", "label": "OMB memo M-22-09, federal zero trust strategy"}]}, {"kind": "multipleChoice", "id": "mc", "prompt": "Which login method did M-22-09 say agencies must stop supporting for routine access?", "options": ["Hardware security keys", "SMS text message codes", "Smart cards with chips"], "correctIndex": 1, "explanation": "SMS and voice codes, one-time codes and push prompts do not resist phishing."}, {"kind": "theCall", "id": "call", "situation": "Your agency uses text-message codes for logins. M-22-09 just landed.", "prompt": "What is your plan?", "options": ["Keep text codes; they are MFA", "Move staff to phishing-resistant MFA", "Force password changes every 30 days"], "consequences": ["The memo says to stop supporting them for routine access.", "That is what the memo requires by the end of fiscal 2024.", "The memo removes forced rotation, not adds it."], "correctIndex": 1, "explanation": "The memo targets phishable methods and outdated password rules alike."}, {"id": "lens-career", "kind": "info", "title": "Know phishing-resistant MFA", "body": "Being able to explain why SMS codes fall short shows you know modern identity security.", "eyebrow": "For your interview", "sources": [{"url": "https://www.whitehouse.gov/wp-content/uploads/2022/01/M-22-09.pdf", "label": "OMB memo M-22-09, federal zero trust strategy"}]}, {"id": "rule", "kind": "microInsight", "text": "In identity security, a login method is only as strong as the easiest way to trick it.", "eyebrow": "The rule", "sources": [{"url": "https://www.whitehouse.gov/wp-content/uploads/2022/01/M-22-09.pdf", "label": "OMB memo M-22-09, federal zero trust strategy"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "OMB memo M-22-09 required phishing-resistant MFA for federal staff by the end of fiscal 2024 and dropped forced password rotation and special-character rules.", "sectionKey": "risk"}]}$ml$::jsonb),
