($ml$7a98fc26-a5ca-5a19-a23a-21139b0e2eeb$ml$::uuid, $ml$cybersecurity$ml$, $ml$The end of the password?$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-24$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d24-career", "title": "The end of the password?", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Passwords are finally being replaced.", "eyebrow": "Day 24 · Where it breaks", "headline": "By December 2024, Google said 800 million accounts used passkeys, and Amazon users had created 175 million.", "fullText": "A passkey lets you sign in with your device, often with a fingerprint or face scan, instead of a password, and it resists phishing. Microsoft said passkey sign-ins were three times faster than passwords and succeeded 98% of the time, against 32% for passwords. It aims to remove passwords completely.", "sources": [{"url": "https://www.biometricupdate.com/202412/passkeys-build-momentum-enabling-access-to-15-billion-online-accounts", "label": "Biometric Update, passkeys build momentum"}]}, {"kind": "microInsight", "id": "how", "eyebrow": "How it works", "text": "A passkey is tied to your device and to the real website.", "highlight": "A fake site cannot collect it the way it collects a password.", "keyTerms": [{"term": "Passkey", "definition": "A phishing-resistant login stored on your device that replaces a password."}], "sources": [{"url": "https://www.biometricupdate.com/202412/passkeys-build-momentum-enabling-access-to-15-billion-online-accounts", "label": "Biometric Update, passkeys build momentum"}]}, {"kind": "microInsight", "id": "success", "eyebrow": "The numbers", "text": "Microsoft saw 98% of passkey sign-ins succeed, versus 32% for passwords.", "highlight": "Fewer failed logins also means fewer help desk calls.", "sources": [{"url": "https://www.biometricupdate.com/202412/passkeys-build-momentum-enabling-access-to-15-billion-online-accounts", "label": "Biometric Update, passkeys build momentum"}]}, {"kind": "info", "id": "gap", "eyebrow": "The gap", "title": "Adoption is still early", "body": "Big platforms support passkeys, but most companies still run on passwords. Moving everyone over is the open problem.", "sources": [{"url": "https://www.biometricupdate.com/202412/passkeys-build-momentum-enabling-access-to-15-billion-online-accounts", "label": "Biometric Update, passkeys build momentum"}]}, {"kind": "numberSense", "id": "ns-success", "prompt": "What share of password sign-ins succeeded, by Microsoft's count, in percent?", "min": 0, "max": 100, "value": 32, "unit": "%", "explanation": "32%, against 98% for passkeys."}, {"kind": "multipleChoice", "id": "mc", "prompt": "What makes a passkey resist phishing?", "options": ["It is tied to the real website", "It is longer than most passwords", "It expires every 30 days"], "correctIndex": 0, "explanation": "A passkey only works with the genuine site, so a fake page cannot collect it."}, {"id": "lens-career", "kind": "info", "title": "Know where identity is heading", "body": "Passkeys are replacing passwords at Google, Amazon and Microsoft. Knowing how they work puts you ahead.", "eyebrow": "For your interview", "sources": [{"url": "https://www.biometricupdate.com/202412/passkeys-build-momentum-enabling-access-to-15-billion-online-accounts", "label": "Biometric Update, passkeys build momentum"}]}, {"id": "rule", "kind": "microInsight", "text": "In identity, the safest password may be no password at all.", "eyebrow": "The rule", "sources": [{"url": "https://www.biometricupdate.com/202412/passkeys-build-momentum-enabling-access-to-15-billion-online-accounts", "label": "Biometric Update, passkeys build momentum"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Passkeys replace passwords with phishing-resistant device logins. Google counted 800 million accounts using them by December 2024, but most companies have not switched.", "sectionKey": "my_view"}]}$ml$::jsonb),
