($ml$cdc8ea2b-8c32-55e2-9e34-dfb05c0c4e27$ml$::uuid, $ml$cybersecurity$ml$, $ml$The end of the password?$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-24$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:curiosity$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d24-curiosity", "title": "The end of the password?", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Passwords are finally being replaced.", "eyebrow": "Day 24 · Where it breaks", "headline": "By December 2024, Google said 800 million accounts used passkeys, and Amazon users had created 175 million.", "fullText": "A passkey lets you sign in with your device, often with a fingerprint or face scan, instead of a password, and it resists phishing. Microsoft said passkey sign-ins were three times faster than passwords and succeeded 98% of the time, against 32% for passwords. It aims to remove passwords completely.", "sources": [{"url": "https://www.biometricupdate.com/202412/passkeys-build-momentum-enabling-access-to-15-billion-online-accounts", "label": "Biometric Update, passkeys build momentum"}]}, {"kind": "microInsight", "id": "how", "eyebrow": "How it works", "text": "A passkey is tied to your device and to the real website.", "highlight": "A fake site cannot collect it the way it collects a password.", "keyTerms": [{"term": "Passkey", "definition": "A phishing-resistant login stored on your device that replaces a password."}], "sources": [{"url": "https://www.biometricupdate.com/202412/passkeys-build-momentum-enabling-access-to-15-billion-online-accounts", "label": "Biometric Update, passkeys build momentum"}]}, {"kind": "microInsight", "id": "success", "eyebrow": "The numbers", "text": "Microsoft saw 98% of passkey sign-ins succeed, versus 32% for passwords.", "highlight": "Fewer failed logins also means fewer help desk calls.", "sources": [{"url": "https://www.biometricupdate.com/202412/passkeys-build-momentum-enabling-access-to-15-billion-online-accounts", "label": "Biometric Update, passkeys build momentum"}]}, {"kind": "info", "id": "gap", "eyebrow": "The gap", "title": "Adoption is still early", "body": "Big platforms support passkeys, but most companies still run on passwords. Moving everyone over is the open problem.", "sources": [{"url": "https://www.biometricupdate.com/202412/passkeys-build-momentum-enabling-access-to-15-billion-online-accounts", "label": "Biometric Update, passkeys build momentum"}]}, {"kind": "numberSense", "id": "ns-success", "prompt": "What share of password sign-ins succeeded, by Microsoft's count, in percent?", "min": 0, "max": 100, "value": 32, "unit": "%", "explanation": "32%, against 98% for passkeys."}, {"kind": "multipleChoice", "id": "mc", "prompt": "What makes a passkey resist phishing?", "options": ["It is tied to the real website", "It is longer than most passwords", "It expires every 30 days"], "correctIndex": 0, "explanation": "A passkey only works with the genuine site, so a fake page cannot collect it."}, {"id": "lens-curiosity", "kind": "info", "title": "Logging in with your face", "body": "800 million Google accounts used passkeys by late 2024, signing in with a device instead of a password.", "eyebrow": "Why it matters", "sources": [{"url": "https://www.biometricupdate.com/202412/passkeys-build-momentum-enabling-access-to-15-billion-online-accounts", "label": "Biometric Update, passkeys build momentum"}]}, {"id": "rule", "kind": "microInsight", "text": "In identity, the safest password may be no password at all.", "eyebrow": "The rule", "sources": [{"url": "https://www.biometricupdate.com/202412/passkeys-build-momentum-enabling-access-to-15-billion-online-accounts", "label": "Biometric Update, passkeys build momentum"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Passkeys replace passwords with phishing-resistant device logins. Google counted 800 million accounts using them by December 2024, but most companies have not switched.", "sectionKey": "frontier"}]}$ml$::jsonb),
($ml$36e8a1af-828c-5240-ac21-c7ea057a3e8d$ml$::uuid, $ml$cybersecurity$ml$, $ml$Never trust, always verify$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-25$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d25-career", "title": "Never trust, always verify", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Being inside the network no longer means being trusted.", "eyebrow": "Day 25 · Zero trust", "headline": "In August 2020, NIST defined zero trust: no implicit trust based on where a user or device sits on the network.", "fullText": "The old model was a castle: a strong wall, with everyone inside trusted. Zero trust moves defenses from the network perimeter to users, assets and resources. Every user and device is authenticated and authorized before each session, wherever it connects from.", "sources": [{"url": "https://csrc.nist.gov/Pubs/sp/800/207/Final", "label": "NIST SP 800-207, Zero Trust Architecture"}]}, {"kind": "microInsight", "id": "castle", "eyebrow": "The old model", "text": "Perimeter security trusts anyone already inside the wall.", "highlight": "One stolen login could open the whole network.", "sources": [{"url": "https://csrc.nist.gov/Pubs/sp/800/207/Final", "label": "NIST SP 800-207, Zero Trust Architecture"}]}, {"kind": "microInsight", "id": "verify", "eyebrow": "The new model", "text": "Zero trust checks the user and the device before every session.", "highlight": "Location alone earns nothing.", "keyTerms": [{"term": "Zero trust", "definition": "A security model that grants no trust based on network location and verifies every access."}], "sources": [{"url": "https://csrc.nist.gov/Pubs/sp/800/207/Final", "label": "NIST SP 800-207, Zero Trust Architecture"}]}, {"kind": "info", "id": "federal", "eyebrow": "In practice", "title": "The US government adopted it", "body": "A 2022 White House memo set zero trust goals for federal agencies to meet by the end of fiscal 2024.", "sources": [{"url": "https://www.whitehouse.gov/wp-content/uploads/2022/01/M-22-09.pdf", "label": "OMB memo M-22-09, federal zero trust strategy"}]}, {"kind": "sortSignal", "id": "sort", "prompt": "Perimeter model or zero trust?", "buckets": ["Perimeter", "Zero trust"], "items": [{"text": "Inside the office network means trusted", "bucket": 0}, {"text": "One VPN login opens everything", "bucket": 0}, {"text": "Every session is verified", "bucket": 1}, {"text": "Device health is checked each time", "bucket": 1}], "explanation": "The perimeter model trusts location. Zero trust verifies each access."}, {"kind": "multipleChoice", "id": "mc", "prompt": "Under zero trust, what earns a device access?", "options": ["Being plugged into the office network", "Passing checks before each session", "Having connected safely last week"], "correctIndex": 1, "explanation": "Authentication and authorization happen before every session, not once."}, {"id": "lens-career", "kind": "info", "title": "Define zero trust exactly", "body": "Say it like NIST: no implicit trust based on network location. Buzzword answers are easy to spot.", "eyebrow": "For your interview", "sources": [{"url": "https://csrc.nist.gov/Pubs/sp/800/207/Final", "label": "NIST SP 800-207, Zero Trust Architecture"}]}, {"id": "rule", "kind": "microInsight", "text": "In network security, location is not identity.", "eyebrow": "The rule", "sources": [{"url": "https://csrc.nist.gov/Pubs/sp/800/207/Final", "label": "NIST SP 800-207, Zero Trust Architecture"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "NIST defined zero trust in 2020 as granting no trust based on network location. Every user and device is verified before each session.", "sectionKey": "players"}]}$ml$::jsonb),
