($ml$25932555-93eb-558a-987b-a968b6b9c2b9$ml$::uuid, $ml$cybersecurity$ml$, $ml$Unplug it within 48 hours$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-27$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d27-career", "title": "Unplug it within 48 hours", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "The door into the network became the target.", "eyebrow": "Day 27 · The power", "headline": "In February 2024, CISA ordered US civilian agencies to disconnect Ivanti VPN products within 48 hours.", "fullText": "Attackers, including suspected Chinese state-backed hackers, were exploiting several zero-day flaws in Ivanti Connect Secure and had bypassed published fixes. One research firm counted at least 2,200 compromised devices. Agencies usually get weeks to patch; this deadline was unusually short.", "sources": [{"url": "https://techcrunch.com/2024/02/01/cisa-federal-agencies-disconnect-ivanti-vpn", "label": "TechCrunch, CISA orders agencies to disconnect Ivanti VPNs"}]}, {"kind": "microInsight", "id": "edge", "eyebrow": "Why edge devices", "text": "VPNs and firewalls sit at the edge, facing the whole internet.", "highlight": "Break one, and you are inside.", "keyTerms": [{"term": "Edge device", "definition": "Equipment such as a VPN or firewall that connects a network to the internet."}], "sources": [{"url": "https://techcrunch.com/2024/02/01/cisa-federal-agencies-disconnect-ivanti-vpn", "label": "TechCrunch, CISA orders agencies to disconnect Ivanti VPNs"}]}, {"kind": "microInsight", "id": "clean", "eyebrow": "The cleanup", "text": "Reconnecting effectively required a fresh, patched install.", "highlight": "Ivanti advised factory resets so attackers could not hang on.", "sources": [{"url": "https://techcrunch.com/2024/02/01/cisa-federal-agencies-disconnect-ivanti-vpn", "label": "TechCrunch, CISA orders agencies to disconnect Ivanti VPNs"}]}, {"kind": "info", "id": "hunt", "eyebrow": "After the unplug", "title": "Assume they got further", "body": "Agencies also had to hunt for threats on connected systems and audit privileged accounts.", "sources": [{"url": "https://techcrunch.com/2024/02/01/cisa-federal-agencies-disconnect-ivanti-vpn", "label": "TechCrunch, CISA orders agencies to disconnect Ivanti VPNs"}]}, {"kind": "multipleChoice", "id": "mc", "prompt": "Why did CISA order the Ivanti VPNs unplugged instead of patched?", "options": ["Attackers were bypassing the fixes", "Ivanti had stopped supporting the VPN", "The VPNs were slowing agency networks"], "correctIndex": 0, "explanation": "Published mitigations were being bypassed, so disconnecting was the safer step."}, {"kind": "theCall", "id": "call", "situation": "Your company runs the same VPN. A patch is out, but attackers are reportedly getting around it.", "prompt": "What do you do?", "options": ["Patch it and move on", "Take it offline and rebuild clean", "Leave it, since you are not a target"], "consequences": ["Fixes were being bypassed.", "CISA required a fresh, patched install for agencies.", "At least 2,200 devices were already compromised."], "correctIndex": 1, "explanation": "When attackers beat the fix, rebuild clean and hunt for intruders."}, {"id": "lens-career", "kind": "info", "title": "Edge devices are hot targets", "body": "VPNs and firewalls are where attackers aim first. Knowing how to respond to an edge flaw is a core skill.", "eyebrow": "For your interview", "sources": [{"url": "https://techcrunch.com/2024/02/01/cisa-federal-agencies-disconnect-ivanti-vpn", "label": "TechCrunch, CISA orders agencies to disconnect Ivanti VPNs"}]}, {"id": "rule", "kind": "microInsight", "text": "In network security, the device facing the internet is the one attackers hit first.", "eyebrow": "The rule", "sources": [{"url": "https://techcrunch.com/2024/02/01/cisa-federal-agencies-disconnect-ivanti-vpn", "label": "TechCrunch, CISA orders agencies to disconnect Ivanti VPNs"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "In February 2024, CISA gave agencies 48 hours to disconnect Ivanti VPNs as attackers bypassed fixes. Edge devices are prime targets.", "sectionKey": "questions"}]}$ml$::jsonb),
