($ml$79b13455-b172-5248-9cc4-e821a483f5f1$ml$::uuid, $ml$cybersecurity$ml$, $ml$48 minutes to spread$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-28$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d28-career", "title": "48 minutes to spread", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Once inside, attackers move fast.", "eyebrow": "Day 28 · The numbers", "headline": "In CrowdStrike's 2025 report, criminal hackers took 48 minutes on average to move beyond their first foothold.", "fullText": "That is breakout time: how long it takes an intruder to move from the first compromised machine to others. The fastest case CrowdStrike recorded was 51 seconds. It also found 79% of attacks to gain initial access were malware-free, often using stolen logins instead.", "sources": [{"url": "https://www.businesswire.com/news/home/20250227012922/en", "label": "CrowdStrike 2025 Global Threat Report release"}]}, {"kind": "microInsight", "id": "breakout", "eyebrow": "The metric", "text": "Breakout time is how long defenders have before an intrusion spreads.", "highlight": "The average was 48 minutes; the fastest, 51 seconds.", "keyTerms": [{"term": "Breakout time", "definition": "How long an intruder takes to move from the first compromised system to others."}], "sources": [{"url": "https://www.businesswire.com/news/home/20250227012922/en", "label": "CrowdStrike 2025 Global Threat Report release"}]}, {"kind": "microInsight", "id": "malware-free", "eyebrow": "The method", "text": "79% of attacks to get in used no malware.", "highlight": "Stolen logins look like normal users, which buys time.", "sources": [{"url": "https://www.businesswire.com/news/home/20250227012922/en", "label": "CrowdStrike 2025 Global Threat Report release"}]}, {"kind": "info", "id": "segment", "eyebrow": "The defense", "title": "Segmentation slows the spread", "body": "Splitting a network into zones, each checked separately, makes moving from one machine to the next harder.", "sources": [{"url": "https://csrc.nist.gov/Pubs/sp/800/207/Final", "label": "NIST SP 800-207, Zero Trust Architecture"}]}, {"kind": "numberSense", "id": "ns-breakout", "prompt": "What was the average eCrime breakout time in CrowdStrike's 2025 report, in minutes?", "min": 0, "max": 120, "value": 48, "unit": "min", "explanation": "48 minutes on average; the fastest was 51 seconds."}, {"kind": "spotFake", "id": "fake", "prompt": "One of these is false. Tap it.", "statements": ["The fastest breakout recorded was 51 seconds.", "Most attacks to get in relied on malware.", "The average breakout time was 48 minutes."], "fakeIndex": 1, "explanation": "79% of attacks to gain initial access were malware-free."}, {"id": "lens-career", "kind": "info", "title": "Speed defines the SOC", "body": "With 48 minutes to contain an intrusion, detection and response speed is what security teams are judged on.", "eyebrow": "For your interview", "sources": [{"url": "https://www.businesswire.com/news/home/20250227012922/en", "label": "CrowdStrike 2025 Global Threat Report release"}]}, {"id": "rule", "kind": "microInsight", "text": "In network defense, you have minutes, not days, once someone is inside.", "eyebrow": "The rule", "sources": [{"url": "https://www.businesswire.com/news/home/20250227012922/en", "label": "CrowdStrike 2025 Global Threat Report release"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "CrowdStrike's 2025 report put average breakout time at 48 minutes, fastest 51 seconds, and found 79% of initial access attacks were malware-free.", "sectionKey": "numbers"}]}$ml$::jsonb),
