($ml$3abcebf4-0f40-5b73-892d-92acaf183e1e$ml$::uuid, $ml$cybersecurity$ml$, $ml$One old password, one shut pipeline$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-29$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d29-career", "title": "One old password, one shut pipeline", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "A forgotten account still worked.", "eyebrow": "Day 29 · The risk", "headline": "In May 2021, Colonial Pipeline shut down its fuel pipeline after hackers got in with one compromised password.", "fullText": "The attackers entered on April 29 through a VPN account that was no longer used but still active, and it had no multifactor authentication. A ransom note appeared on May 7, and the pipeline, which carries about 2.5 million barrels of fuel a day, stayed shut until May 12. Colonial paid a $4.4 million ransom.", "sources": [{"url": "https://www.aljazeera.com/economy/2021/6/4/hackers-breached-colonial-pipeline-with-one-compromised-password", "label": "Al Jazeera, Colonial Pipeline breached with one password"}]}, {"kind": "microInsight", "id": "dormant", "eyebrow": "The opening", "text": "The account was no longer in use but had never been switched off.", "highlight": "Its password later turned up in a batch of leaked passwords.", "sources": [{"url": "https://www.aljazeera.com/economy/2021/6/4/hackers-breached-colonial-pipeline-with-one-compromised-password", "label": "Al Jazeera, Colonial Pipeline breached with one password"}]}, {"kind": "microInsight", "id": "flat", "eyebrow": "The design flaw", "text": "A VPN login gave network access with just a password.", "highlight": "No second factor stood in the way.", "sources": [{"url": "https://www.aljazeera.com/economy/2021/6/4/hackers-breached-colonial-pipeline-with-one-compromised-password", "label": "Al Jazeera, Colonial Pipeline 