($ml$34e48d3b-815d-5ef2-b616-b5e0373fbfa9$ml$::uuid, $ml$cybersecurity$ml$, $ml$Encryption for the quantum age$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-30$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d30-career", "title": "Encryption for the quantum age", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Steal it now, read it later.", "eyebrow": "Day 30 · Where it breaks", "headline": "In August 2024, NIST published its first three post-quantum encryption standards.", "fullText": "FIPS 203 covers general encryption, and FIPS 204 and FIPS 205 cover digital signatures. They are built to resist future quantum computers that could break much of today's encryption. The worry is harvest now, decrypt later: attackers collect encrypted data today and read it once such machines exist.", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"kind": "microInsight", "id": "harvest", "eyebrow": "The threat", "text": "Data stolen today can be decrypted years from now.", "highlight": "Secrets that must last a decade are already at risk.", "keyTerms": [{"term": "Post-quantum cryptography", "definition": "Encryption designed to stay secure against future quantum computers."}], "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"kind": "microInsight", "id": "clock", "eyebrow": "The clock", "text": "The release started a one-year clock for further federal guidance.", "highlight": "Agencies are expected to migrate quickly once that guidance lands.", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"kind": "info", "id": "gap", "eyebrow": "The gap", "title": "Finding all the old encryption", "body": "Companies must first find every place they use vulnerable encryption before they can replace it.", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"kind": "multipleChoice", "id": "mc", "prompt": "What does \"harvest now, decrypt later\" mean?", "options": ["Collect encrypted data to read it later", "Back up data before a ransomware attack", "Encrypt data twice to be safe"], "correctIndex": 0, "explanation": "Attackers store encrypted data now and decrypt it once quantum computers can break it."}, {"kind": "theCall", "id": "call", "situation": "Your bank keeps customer records that must stay secret for 20 years.", "prompt": "What do you do about quantum risk?", "options": ["Wait until quantum computers exist", "Inventory encryption and plan migration", "Delete all records older than a year"], "consequences": ["Data harvested today could be read later.", "You cannot replace encryption you have not found.", "Deleting records may break laws and serve no one."], "correctIndex": 1, "explanation": "Long-lived secrets are exposed now, so the inventory and migration plan should start now."}, {"id": "lens-career", "kind": "info", "title": "Post-quantum is a new specialty", "body": "Migrating to NIST's new standards will take years. People who understand it will be in demand.", "eyebrow": "For your interview", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"id": "rule", "kind": "microInsight", "text": "In cryptography, you protect today's secrets against tomorrow's machines.", "eyebrow": "The rule", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "NIST released its first three post-quantum standards in August 2024. Data harvested today could be decrypted later, so migration planning starts now.", "sectionKey": "my_view"}]}$ml$::jsonb),
($ml$465de6d5-2ec5-5d4b-b2da-4976269fd278$ml$::uuid, $ml$cybersecurity$ml$, $ml$Encryption for the quantum age$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-30$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:invest$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d30-invest", "title": "Encryption for the quantum age", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Steal it now, read it later.", "eyebrow": "Day 30 · Where it breaks", "headline": "In August 2024, NIST published its first three post-quantum encryption standards.", "fullText": "FIPS 203 covers general encryption, and FIPS 204 and FIPS 205 cover digital signatures. They are built to resist future quantum computers that could break much of today's encryption. The worry is harvest now, decrypt later: attackers collect encrypted data today and read it once such machines exist.", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"kind": "microInsight", "id": "harvest", "eyebrow": "The threat", "text": "Data stolen today can be decrypted years from now.", "highlight": "Secrets that must last a decade are already at risk.", "keyTerms": [{"term": "Post-quantum cryptography", "definition": "Encryption designed to stay secure against future quantum computers."}], "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"kind": "microInsight", "id": "clock", "eyebrow": "The clock", "text": "The release started a one-year clock for further federal guidance.", "highlight": "Agencies are expected to migrate quickly once that guidance lands.", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"kind": "info", "id": "gap", "eyebrow": "The gap", "title": "Finding all the old encryption", "body": "Companies must first find every place they use vulnerable encryption before they can replace it.", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"kind": "multipleChoice", "id": "mc", "prompt": "What does \"harvest now, decrypt later\" mean?", "options": ["Collect encrypted data to read it later", "Back up data before a ransomware attack", "Encrypt data twice to be safe"], "correctIndex": 0, "explanation": "Attackers store encrypted data now and decrypt it once quantum computers can break it."}, {"kind": "theCall", "id": "call", "situation": "Your bank keeps customer records that must stay secret for 20 years.", "prompt": "What do you do about quantum risk?", "options": ["Wait until quantum computers exist", "Inventory encryption and plan migration", "Delete all records older than a year"], "consequences": ["Data harvested today could be read later.", "You cannot replace encryption you have not found.", "Deleting records may break laws and serve no one."], "correctIndex": 1, "explanation": "Long-lived secrets are exposed now, so the inventory and migration plan should start now."}, {"id": "lens-invest", "kind": "info", "title": "A forced upgrade cycle", "body": "Replacing encryption across every system creates years of spending on tools and services.", "eyebrow": "For investors", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"id": "rule", "kind": "microInsight", "text": "In cryptography, you protect today's secrets against tomorrow's machines.", "eyebrow": "The rule", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "NIST released its first three post-quantum standards in August 2024. Data harvested today could be decrypted later, so migration planning starts now.", "sectionKey": "review"}]}$ml$::jsonb),
($ml$6ac3d7f2-a838-56dc-9439-4b5c5a25db2b$ml$::uuid, $ml$cybersecurity$ml$, $ml$Encryption for the quantum age$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-30$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:build_startup$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d30-build_startup", "title": "Encryption for the quantum age", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Steal it now, read it later.", "eyebrow": "Day 30 · Where it breaks", "headline": "In August 2024, NIST published its first three post-quantum encryption standards.", "fullText": "FIPS 203 covers general encryption, and FIPS 204 and FIPS 205 cover digital signatures. They are built to resist future quantum computers that could break much of today's encryption. The worry is harvest now, decrypt later: attackers collect encrypted data today and read it once such machines exist.", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"kind": "microInsight", "id": "harvest", "eyebrow": "The threat", "text": "Data stolen today can be decrypted years from now.", "highlight": "Secrets that must last a decade are already at risk.", "keyTerms": [{"term": "Post-quantum cryptography", "definition": "Encryption designed to stay secure against future quantum computers."}], "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"kind": "microInsight", "id": "clock", "eyebrow": "The clock", "text": "The release started a one-year clock for further federal guidance.", "highlight": "Agencies are expected to migrate quickly once that guidance lands.", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"kind": "info", "id": "gap", "eyebrow": "The gap", "title": "Finding all the old encryption", "body": "Companies must first find every place they use vulnerable encryption before they can replace it.", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"kind": "multipleChoice", "id": "mc", "prompt": "What does \"harvest now, decrypt later\" mean?", "options": ["Collect encrypted data to read it later", "Back up data before a ransomware attack", "Encrypt data twice to be safe"], "correctIndex": 0, "explanation": "Attackers store encrypted data now and decrypt it once quantum computers can break it."}, {"kind": "theCall", "id": "call", "situation": "Your bank keeps customer records that must stay secret for 20 years.", "prompt": "What do you do about quantum risk?", "options": ["Wait until quantum computers exist", "Inventory encryption and plan migration", "Delete all records older than a year"], "consequences": ["Data harvested today could be read later.", "You cannot replace encryption you have not found.", "Deleting records may break laws and serve no one."], "correctIndex": 1, "explanation": "Long-lived secrets are exposed now, so the inventory and migration plan should start now."}, {"id": "lens-build_startup", "kind": "info", "title": "Map the old encryption", "body": "Companies do not know where all their vulnerable encryption lives. Finding it is the first product.", "eyebrow": "For founders", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"id": "rule", "kind": "microInsight", "text": "In cryptography, you protect today's secrets against tomorrow's machines.", "eyebrow": "The rule", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "NIST released its first three post-quantum standards in August 2024. Data harvested today could be decrypted later, so migration planning starts now.", "sectionKey": "first_test"}]}$ml$::jsonb),
($ml$617c38fb-7c7b-5133-af76-11fdda570b4d$ml$::uuid, $ml$cybersecurity$ml$, $ml$Encryption for the quantum age$ml$, 'MICRO_LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-30$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:curiosity$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "cybersecurity-d30-curiosity", "title": "Encryption for the quantum age", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Steal it now, read it later.", "eyebrow": "Day 30 · Where it breaks", "headline": "In August 2024, NIST published its first three post-quantum encryption standards.", "fullText": "FIPS 203 covers general encryption, and FIPS 204 and FIPS 205 cover digital signatures. They are built to resist future quantum computers that could break much of today's encryption. The worry is harvest now, decrypt later: attackers collect encrypted data today and read it once such machines exist.", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"kind": "microInsight", "id": "harvest", "eyebrow": "The threat", "text": "Data stolen today can be decrypted years from now.", "highlight": "Secrets that must last a decade are already at risk.", "keyTerms": [{"term": "Post-quantum cryptography", "definition": "Encryption designed to stay secure against future quantum computers."}], "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"kind": "microInsight", "id": "clock", "eyebrow": "The clock", "text": "The release started a one-year clock for further federal guidance.", "highlight": "Agencies are expected to migrate quickly once that guidance lands.", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"kind": "info", "id": "gap", "eyebrow": "The gap", "title": "Finding all the old encryption", "body": "Companies must first find every place they use vulnerable encryption before they can replace it.", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"kind": "multipleChoice", "id": "mc", "prompt": "What does \"harvest now, decrypt later\" mean?", "options": ["Collect encrypted data to read it later", "Back up data before a ransomware attack", "Encrypt data twice to be safe"], "correctIndex": 0, "explanation": "Attackers store encrypted data now and decrypt it once quantum computers can break it."}, {"kind": "theCall", "id": "call", "situation": "Your bank keeps customer records that must stay secret for 20 years.", "prompt": "What do you do about quantum risk?", "options": ["Wait until quantum computers exist", "Inventory encryption and plan migration", "Delete all records older than a year"], "consequences": ["Data harvested today could be read later.", "You cannot replace encryption you have not found.", "Deleting records may break laws and serve no one."], "correctIndex": 1, "explanation": "Long-lived secrets are exposed now, so the inventory and migration plan should start now."}, {"id": "lens-curiosity", "kind": "info", "title": "Codes for future computers", "body": "Encryption is being rebuilt now to resist computers that do not fully exist yet.", "eyebrow": "Why it matters", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"id": "rule", "kind": "microInsight", "text": "In cryptography, you protect today's secrets against tomorrow's machines.", "eyebrow": "The rule", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "NIST released its first three post-quantum standards in August 2024. Data harvested today could be decrypted later, so migration planning starts now.", "sectionKey": "frontier"}]}$ml$::jsonb)
INSERT INTO slides (id, stack_id, slide_number, title, body, sources) VALUES
($ml$dc783a9e-43cf-56a7-a70b-17757e0e91f4$ml$::uuid, $ml$873be961-dc54-592e-bbc8-6d7e61b77a59$ml$::uuid, 1, $ml$Day 6 · Where it breaks$ml$, $ml$By December 2024, US officials said China-linked hackers had breached nine US telecom companies. The campaign, called Salt Typhoon, took customer call records and reached the private communications of a limited number of people, believed to include senior US officials. The White House said voluntary security practices were inadequate against China, and the FCC was set to take up required rules for telecom companies.$ml$, $ml$[{"url": "https://www.pbs.org/newshour/world/chinese-hacking-campaign-hit-a-9th-u-s-telecom-firm-white-house-says", "label": "PBS NewsHour, Chinese hacking campaign hit a 9th US telecom"}]$ml$::jsonb),
($ml$1b327c92-d82f-51d1-b519-e79ed237e213$ml$::uuid, $ml$873be961-dc54-592e-bbc8-6d7e61b77a59$ml$::uuid, 2, $ml$The target$ml$, $ml$The goal was to know who calls whom, then listen to chosen targets. The FBI said most targets were involved in government or politics.$ml$, $ml$[{"url": "https://www.pbs.org/newshour/world/chinese-hacking-campaign-hit-a-9th-u-s-telecom-firm-white-house-says", "label": "PBS NewsHour, Chinese hacking campaign hit a 9th US telecom"}]$ml$::jsonb),
($ml$f2ae5116-f030-54a6-9061-de625d1b60f8$ml$::uuid, $ml$873be961-dc54-592e-bbc8-6d7e61b77a59$ml$::uuid, 3, $ml$The scale$ml$, $ml$At least eight US telecoms were named first, then a ninth. Officials said dozens of countries were affected.$ml$, $ml$[{"url": "https://www.pbs.org/newshour/world/chinese-hacking-campaign-hit-a-9th-u-s-telecom-firm-white-house-says", "label": "PBS NewsHour, Chinese hacking campaign hit a 9th US telecom"}]$ml$::jsonb),
($ml$0b946fc2-5414-5961-b78b-0c14fd75cc6c$ml$::uuid, $ml$873be961-dc54-592e-bbc8-6d7e61b77a59$ml$::uuid, 4, $ml$Voluntary security was not enough$ml$, $ml$Telecom security had largely been voluntary. Officials called that inadequate and pushed for required practices.$ml$, $ml$[{"url": "https://www.pbs.org/newshour/world/chinese-hacking-campaign-hit-a-9th-u-s-telecom-firm-white-house-says", "label": "PBS NewsHour, Chinese hacking campaign hit a 9th US telecom"}]$ml$::jsonb),
($ml$07921d79-b74d-5db0-9fbd-dc63c8cf638c$ml$::uuid, $ml$873be961-dc54-592e-bbc8-6d7e61b77a59$ml$::uuid, 5, $ml$Know the telecom wake-up call$ml$, $ml$Salt Typhoon reached nine US carriers. Mentioning it shows you follow nation-state threats, not just ransomware.$ml$, $ml$[{"url": "https://www.pbs.org/newshour/world/chinese-hacking-campaign-hit-a-9th-u-s-telecom-firm-white-house-says", "label": "PBS NewsHour, Chinese hacking campaign hit a 9th US telecom"}]$ml$::jsonb),
($ml$75e47927-c293-5d93-ab43-adf964279bda$ml$::uuid, $ml$873be961-dc54-592e-bbc8-6d7e61b77a59$ml$::uuid, 6, $ml$The rule$ml$, $ml$In cyber, the most valuable target is often the network everyone else depends on.$ml$, $ml$[{"url": "https://www.pbs.org/newshour/world/chinese-hacking-campaign-hit-a-9th-u-s-telecom-firm-white-house-says", "label": "PBS NewsHour, Chinese hacking campaign hit a 9th US telecom"}]$ml$::jsonb),
($ml$3946289e-dbb5-5c70-bdb5-03c35e2d58c8$ml$::uuid, $ml$df9b6dbc-28e4-5b2e-9d2c-e730a962b038$ml$::uuid, 1, $ml$Day 6 · Where it breaks$ml$, $ml$By December 2024, US officials said China-linked hackers had breached nine US telecom companies. The campaign, called Salt Typhoon, took customer call records and reached the private communications of a limited number of people, believed to include senior US officials. The White House said voluntary security practices were inadequate against China, and the FCC was set to take up required rules for telecom companies.$ml$, $ml$[{"url": "https://www.pbs.org/newshour/world/chinese-hacking-campaign-hit-a-9th-u-s-telecom-firm-white-house-says", "label": "PBS NewsHour, Chinese hacking campaign hit a 9th US telecom"}]$ml$::jsonb),
($ml$0681de17-199c-5d78-bec5-2c5e7bee5deb$ml$::uuid, $ml$df9b6dbc-28e4-5b2e-9d2c-e730a962b038$ml$::uuid, 2, $ml$The target$ml$, $ml$The goal was to know who calls whom, then listen to chosen targets. The FBI said most targets were involved in government or politics.$ml$, $ml$[{"url": "https://www.pbs.org/newshour/world/chinese-hacking-campaign-hit-a-9th-u-s-telecom-firm-white-house-says", "label": "PBS NewsHour, Chinese hacking campaign hit a 9th US telecom"}]$ml$::jsonb),
($ml$edc3a035-1443-526d-8381-d1bb377e6fd7$ml$::uuid, $ml$df9b6dbc-28e4-5b2e-9d2c-e730a962b038$ml$::uuid, 3, $ml$The scale$ml$, $ml$At least eight US telecoms were named first, then a ninth. Officials said dozens of countries were affected.$ml$, $ml$[{"url": "https://www.pbs.org/newshour/world/chinese-hacking-campaign-hit-a-9th-u-s-telecom-firm-white-house-says", "label": "PBS NewsHour, Chinese hacking campaign hit a 9th US telecom"}]$ml$::jsonb),
