($ml$fdc96701-c43f-5477-b36b-e63514d2fb48$ml$::uuid, $ml$df9b6dbc-28e4-5b2e-9d2c-e730a962b038$ml$::uuid, 5, $ml$New rules mean new spending$ml$, $ml$Officials pushed telecoms from voluntary to required security. Mandates like that create budgets for security vendors.$ml$, $ml$[{"url": "https://www.pbs.org/newshour/world/chinese-hacking-campaign-hit-a-9th-u-s-telecom-firm-white-house-says", "label": "PBS NewsHour, Chinese hacking campaign hit a 9th US telecom"}]$ml$::jsonb),
