($ml$87bd2ea5-9c59-501c-9e5a-91a121e17f0c$ml$::uuid, $ml$34d2d52e-bf53-5d5f-9d55-2c0ad8693298$ml$::uuid, 2, $ml$The ID$ml$, $ml$Each public flaw gets a CVE number, so everyone can name the same bug. Scores run from 0 to 10; 231 flaws scored a perfect 10 in 2024.$ml$, $ml$[{"url": "https://jerrygamblin.com/2025/01/05/2024-cve-data-review/", "label": "Jerry Gamblin, 2024 CVE data review"}]$ml$::jsonb),
