($ml$4d6280fa-7caa-533e-884a-c24f0df100de$ml$::uuid, $ml$34d2d52e-bf53-5d5f-9d55-2c0ad8693298$ml$::uuid, 4, $ml$Defenders cannot patch everything at once$ml$, $ml$At about 108 new flaws a day, teams rank them by how likely and how damaging an attack would be. The average severity score in 2024 was 6.67 out of 10.$ml$, $ml$[{"url": "https://jerrygamblin.com/2025/01/05/2024-cve-data-review/", "label": "Jerry Gamblin, 2024 CVE data review"}]$ml$::jsonb),
($ml$bade4795-c987-5398-8220-8aa64534d9fd$ml$::uuid, $ml$34d2d52e-bf53-5d5f-9d55-2c0ad8693298$ml$::uuid, 5, $ml$Prioritizing is the pain$ml$, $ml$About 108 new CVEs a day is more than any team can handle. Helping teams pick the few that matter is a real need.$ml$, $ml$[{"url": "https://jerrygamblin.com/2025/01/05/2024-cve-data-review/", "label": "Jerry Gamblin, 2024 CVE data review"}]$ml$::jsonb),
