($ml$b632e873-db9e-5243-8ce4-a4945aed2e33$ml$::uuid, $ml$2853a208-799b-5d37-96df-ad7ba8a55f32$ml$::uuid, 5, $ml$Security spend includes outsiders$ml$, $ml$Big tech pays millions a year to outside researchers. Bounty platforms sit between both sides.$ml$, $ml$[{"url": "https://www.techradar.com/pro/security/google-bug-bounty-payments-hit-nearly-usd12-million-in-2024", "label": "TechRadar, Google bug bounty payments in 2024"}]$ml$::jsonb),
