($ml$2870f016-2e7e-57f0-b448-6f7011c6f2e7$ml$::uuid, $ml$9127075c-b7b3-5249-8bb6-ddac3abc0c45$ml$::uuid, 2, $ml$The bar$ml$, $ml$The catalog lists only flaws attackers are actually using. That turns 40,000 a year into a short, urgent list.$ml$, $ml$[{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}, {"url": "https://jerrygamblin.com/2025/01/05/2024-cve-data-review/", "label": "Jerry Gamblin, 2024 CVE data review"}]$ml$::jsonb),
($ml$1b6c78d8-04c7-576a-a07f-d7c110e5c61e$ml$::uuid, $ml$9127075c-b7b3-5249-8bb6-ddac3abc0c45$ml$::uuid, 3, $ml$The follow-up$ml$, $ml$Agencies must report their progress, not just promise it. Status goes to a federal dashboard CISA can watch.$ml$, $ml$[{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}]$ml$::jsonb),
($ml$ca0e6482-7e79-556a-bd2d-1e236ba7808e$ml$::uuid, $ml$9127075c-b7b3-5249-8bb6-ddac3abc0c45$ml$::uuid, 4, $ml$CISA sets the deadline$ml$, $ml$Once a flaw is listed, federal agencies have no choice about urgency. CISA can shorten deadlines in cases of grave risk.$ml$, $ml$[{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}]$ml$::jsonb),
($ml$33197ec9-cfad-5013-9a0e-0e3eff81419e$ml$::uuid, $ml$9127075c-b7b3-5249-8bb6-ddac3abc0c45$ml$::uuid, 5, $ml$Deadlines create demand$ml$, $ml$Two-week federal deadlines push agencies to buy tools that find and fix flaws fast.$ml$, $ml$[{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}]$ml$::jsonb),
($ml$8aca26ac-c27f-5a7d-9924-2959940fd20c$ml$::uuid, $ml$9127075c-b7b3-5249-8bb6-ddac3abc0c45$ml$::uuid, 6, $ml$The rule$ml$, $ml$In cyber, whoever decides what is urgent shapes where defenders spend their time.$ml$, $ml$[{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}]$ml$::jsonb),
($ml$a1da7cf2-7ee1-574b-8110-69ee8db868fc$ml$::uuid, $ml$92aae22c-2e79-5ea9-bb71-7c093fd659d9$ml$::uuid, 1, $ml$Day 9 · The power$ml$, $ml$Under CISA's directive BOD 22-01, US civilian agencies must fix listed flaws within two weeks. CISA keeps the Known Exploited Vulnerabilities catalog. A flaw goes on it only with a CVE ID, clear remediation guidance and reliable evidence it is being exploited in the wild. Agencies get two weeks for most listed flaws and six months for those with CVE IDs from before 2021.$ml$, $ml$[{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}]$ml$::jsonb),
($ml$d1b6a1aa-0387-56dd-8c10-bd412352d3fd$ml$::uuid, $ml$92aae22c-2e79-5ea9-bb71-7c093fd659d9$ml$::uuid, 2, $ml$The bar$ml$, $ml$The catalog lists only flaws attackers are actually using. That turns 40,000 a year into a short, urgent list.$ml$, $ml$[{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}, {"url": "https://jerrygamblin.com/2025/01/05/2024-cve-data-review/", "label": "Jerry Gamblin, 2024 CVE data review"}]$ml$::jsonb),
($ml$5bf46e18-d496-55b9-9495-291cecc25b74$ml$::uuid, $ml$92aae22c-2e79-5ea9-bb71-7c093fd659d9$ml$::uuid, 3, $ml$The follow-up$ml$, $ml$Agencies must report their progress, not just promise it. Status goes to a federal dashboard CISA can watch.$ml$, $ml$[{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}]$ml$::jsonb),
($ml$60c83d1f-565a-5000-ad8b-e765184ee9c9$ml$::uuid, $ml$92aae22c-2e79-5ea9-bb71-7c093fd659d9$ml$::uuid, 4, $ml$CISA sets the deadline$ml$, $ml$Once a flaw is listed, federal agencies have no choice about urgency. CISA can shorten deadlines in cases of grave risk.$ml$, $ml$[{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}]$ml$::jsonb),
($ml$2d3fc00c-51c7-5f9c-99d8-bde5c1c25b6c$ml$::uuid, $ml$92aae22c-2e79-5ea9-bb71-7c093fd659d9$ml$::uuid, 5, $ml$Build around the list$ml$, $ml$The catalog is a public, trusted priority list. Products that map it to a customer's systems save real time.$ml$, $ml$[{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}]$ml$::jsonb),
($ml$abd95721-caed-5824-9bac-1889529aa7ff$ml$::uuid, $ml$92aae22c-2e79-5ea9-bb71-7c093fd659d9$ml$::uuid, 6, $ml$The rule$ml$, $ml$In cyber, whoever decides what is urgent shapes where defenders spend their time.$ml$, $ml$[{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}]$ml$::jsonb),
($ml$2cb20c83-7d8e-5a24-bbe6-49302097c495$ml$::uuid, $ml$ce13825a-5b4f-54ca-9b1b-98774ae3e815$ml$::uuid, 1, $ml$Day 9 · The power$ml$, $ml$Under CISA's directive BOD 22-01, US civilian agencies must fix listed flaws within two weeks. CISA keeps the Known Exploited Vulnerabilities catalog. A flaw goes on it only with a CVE ID, clear remediation guidance and reliable evidence it is being exploited in the wild. Agencies get two weeks for most listed flaws and six months for those with CVE IDs from before 2021.$ml$, $ml$[{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}]$ml$::jsonb),
($ml$79fe79b9-aec4-544a-bcb9-3ccfeef16fff$ml$::uuid, $ml$ce13825a-5b4f-54ca-9b1b-98774ae3e815$ml$::uuid, 2, $ml$The bar$ml$, $ml$The catalog lists only flaws attackers are actually using. That turns 40,000 a year into a short, urgent list.$ml$, $ml$[{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}, {"url": "https://jerrygamblin.com/2025/01/05/2024-cve-data-review/", "label": "Jerry Gamblin, 2024 CVE data review"}]$ml$::jsonb),
($ml$5e227eba-57fd-529a-b6c3-cd734cf10777$ml$::uuid, $ml$ce13825a-5b4f-54ca-9b1b-98774ae3e815$ml$::uuid, 3, $ml$The follow-up$ml$, $ml$Agencies must report their progress, not just promise it. Status goes to a federal dashboard CISA can watch.$ml$, $ml$[{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}]$ml$::jsonb),
($ml$f29a8684-de01-5f0c-ad28-c10c4bc88487$ml$::uuid, $ml$ce13825a-5b4f-54ca-9b1b-98774ae3e815$ml$::uuid, 4, $ml$CISA sets the deadline$ml$, $ml$Once a flaw is listed, federal agencies have no choice about urgency. CISA can shorten deadlines in cases of grave risk.$ml$, $ml$[{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}]$ml$::jsonb),
($ml$de7abdd6-b8c9-5341-af9d-a65a6bf7adb3$ml$::uuid, $ml$ce13825a-5b4f-54ca-9b1b-98774ae3e815$ml$::uuid, 5, $ml$A list of active threats$ml$, $ml$CISA keeps a public list of flaws attackers are using right now, and agencies must fix them on a clock.$ml$, $ml$[{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}]$ml$::jsonb),
($ml$662aa56e-1ee5-53fd-9f68-b6f9a4ad18d9$ml$::uuid, $ml$ce13825a-5b4f-54ca-9b1b-98774ae3e815$ml$::uuid, 6, $ml$The rule$ml$, $ml$In cyber, whoever decides what is urgent shapes where defenders spend their time.$ml$, $ml$[{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}]$ml$::jsonb),
($ml$93bc791a-efac-5c02-9dac-492fd245e80b$ml$::uuid, $ml$00c64978-8f57-57cd-8ab2-331af784507a$ml$::uuid, 1, $ml$Day 10 · The numbers$ml$, $ml$In 2023, attackers exploited newly disclosed flaws in five days on average, down from 63. Mandiant measures time-to-exploit: the days between a flaw becoming known and its first use in attacks. It averaged 63 days in 2018 and 2019, 32 days in 2021 and 2022, and five days in 2023. Of 138 exploited flaws it tracked from 2023, 97 were zero-days.$ml$, $ml$[{"url": "https://cloud.google.com/blog/topics/threat-intelligence/time-to-exploit-trends-2023?hl=en", "label": "Google Cloud (Mandiant), time-to-exploit trends 2023"}]$ml$::jsonb),
($ml$57c9c817-a679-516b-8062-b8fd866cf2a8$ml$::uuid, $ml$00c64978-8f57-57cd-8ab2-331af784507a$ml$::uuid, 2, $ml$The metric$ml$, $ml$Time-to-exploit is how long defenders have before attacks start. It fell from 63 days to five in about five years.$ml$, $ml$[{"url": "https://cloud.google.com/blog/topics/threat-intelligence/time-to-exploit-trends-2023?hl=en", "label": "Google Cloud (Mandiant), time-to-exploit trends 2023"}]$ml$::jsonb),
($ml$a1b251de-95ae-576b-928e-a1f7d95a202c$ml$::uuid, $ml$00c64978-8f57-57cd-8ab2-331af784507a$ml$::uuid, 3, $ml$The mix$ml$, $ml$About 70% of the exploited flaws Mandiant tracked were zero-days. For those, there was no patch to apply in time.$ml$, $ml$[{"url": "https://cloud.google.com/blog/topics/threat-intelligence/time-to-exploit-trends-2023?hl=en", "label": "Google Cloud (Mandiant), time-to-exploit trends 2023"}]$ml$::jsonb),
($ml$ab0fc608-3bf4-5ff0-9c24-78010c07fa6a$ml$::uuid, $ml$00c64978-8f57-57cd-8ab2-331af784507a$ml$::uuid, 4, $ml$Averages hide long tails$ml$, $ml$Mandiant left out 15 outliers. With them, the 2023 average rises from five days to 47.$ml$, $ml$[{"url": "https://cloud.google.com/blog/topics/threat-intelligence/time-to-exploit-trends-2023?hl=en", "label": "Google Cloud (Mandiant), time-to-exploit trends 2023"}]$ml$::jsonb),
($ml$c04937e0-0efc-548c-ad23-84994f031456$ml$::uuid, $ml$00c64978-8f57-57cd-8ab2-331af784507a$ml$::uuid, 5, $ml$Quote the shrinking window$ml$, $ml$Five days to exploit, down from 63. That one number explains why patch speed is a job in itself.$ml$, $ml$[{"url": "https://cloud.google.com/blog/topics/threat-intelligence/time-to-exploit-trends-2023?hl=en", "label": "Google Cloud (Mandiant), time-to-exploit trends 2023"}]$ml$::jsonb),
($ml$e2c949fa-3b3c-5b78-91d1-7d215595e815$ml$::uuid, $ml$00c64978-8f57-57cd-8ab2-331af784507a$ml$::uuid, 6, $ml$The rule$ml$, $ml$In cyber, defenders are racing a clock that keeps getting shorter.$ml$, $ml$[{"url": "https://cloud.google.com/blog/topics/threat-intelligence/time-to-exploit-trends-2023?hl=en", "label": "Google Cloud (Mandiant), time-to-exploit trends 2023"}]$ml$::jsonb),
($ml$b9d2f837-980c-5feb-9abd-5777fe25ec21$ml$::uuid, $ml$26953e6e-e4f6-5ff4-961a-450359723369$ml$::uuid, 1, $ml$Day 10 · The numbers$ml$, $ml$In 2023, attackers exploited newly disclosed flaws in five days on average, down from 63. Mandiant measures time-to-exploit: the days between a flaw becoming known and its first use in attacks. It averaged 63 days in 2018 and 2019, 32 days in 2021 and 2022, and five days in 2023. Of 138 exploited flaws it tracked from 2023, 97 were zero-days.$ml$, $ml$[{"url": "https://cloud.google.com/blog/topics/threat-intelligence/time-to-exploit-trends-2023?hl=en", "label": "Google Cloud (Mandiant), time-to-exploit trends 2023"}]$ml$::jsonb),
($ml$651810a9-9273-5330-8e13-db4d9c6e92f3$ml$::uuid, $ml$26953e6e-e4f6-5ff4-961a-450359723369$ml$::uuid, 2, $ml$The metric$ml$, $ml$Time-to-exploit is how long defenders have before attacks start. It fell from 63 days to five in about five years.$ml$, $ml$[{"url": "https://cloud.google.com/blog/topics/threat-intelligence/time-to-exploit-trends-2023?hl=en", "label": "Google Cloud (Mandiant), time-to-exploit trends 2023"}]$ml$::jsonb),
($ml$09801a44-799e-561f-bbdd-19e168844a4c$ml$::uuid, $ml$26953e6e-e4f6-5ff4-961a-450359723369$ml$::uuid, 3, $ml$The mix$ml$, $ml$About 70% of the exploited flaws Mandiant tracked were zero-days. For those, there was no patch to apply in time.$ml$, $ml$[{"url": "https://cloud.google.com/blog/topics/threat-intelligence/time-to-exploit-trends-2023?hl=en", "label": "Google Cloud (Mandiant), time-to-exploit trends 2023"}]$ml$::jsonb),
($ml$7df620fc-19cc-50cb-a2cc-7bcb01ced730$ml$::uuid, $ml$26953e6e-e4f6-5ff4-961a-450359723369$ml$::uuid, 4, $ml$Averages hide long tails$ml$, $ml$Mandiant left out 15 outliers. With them, the 2023 average rises from five days to 47.$ml$, $ml$[{"url": "https://cloud.google.com/blog/topics/threat-intelligence/time-to-exploit-trends-2023?hl=en", "label": "Google Cloud (Mandiant), time-to-exploit trends 2023"}]$ml$::jsonb),
