($ml$9e191a09-27d4-545d-962b-bf01d6f1436b$ml$::uuid, $ml$ea1deba3-7d7c-59b0-b116-77263b0f672a$ml$::uuid, 2, $ml$The metric$ml$, $ml$Time-to-exploit is how long defenders have before attacks start. It fell from 63 days to five in about five years.$ml$, $ml$[{"url": "https://cloud.google.com/blog/topics/threat-intelligence/time-to-exploit-trends-2023?hl=en", "label": "Google Cloud (Mandiant), time-to-exploit trends 2023"}]$ml$::jsonb),
