($ml$d7c6f1b5-7b12-5c95-b1a6-77d8fc4bf2b3$ml$::uuid, $ml$cd5c1ac7-a3a9-505d-bbe4-95dd096e10f3$ml$::uuid, 5, $ml$Frameworks create recurring spend$ml$, $ml$Audits and certifications repeat. That makes compliance work a steady line in security budgets.$ml$, $ml$[{"url": "https://cpl.thalesgroup.com/insights/cybersecurity/what-is-soc-2-compliance", "label": "Thales, what is SOC 2 compliance"}, {"url": "https://webcf.waybackmachine.org/web/20230531192221/https://www.iso.org/isoiec-27001-information-security.html", "label": "ISO, ISO/IEC 27001 information security management"}]$ml$::jsonb),
