($ml$a0d21fe0-daa7-522a-906d-17984164b72b$ml$::uuid, $ml$a9793996-58d5-5248-8345-12a0f99f833f$ml$::uuid, 3, $ml$ISO/IEC 27001$ml$, $ml$ISO 27001 is the best-known standard for running information security as a managed system. Its current edition was published in October 2022.$ml$, $ml$[{"url": "https://webcf.waybackmachine.org/web/20230531192221/https://www.iso.org/isoiec-27001-information-security.html", "label": "ISO, ISO/IEC 27001 information security management"}]$ml$::jsonb),
($ml$9a2cfb5e-a9ab-5928-bcc6-b3f498f63f18$ml$::uuid, $ml$a9793996-58d5-5248-8345-12a0f99f833f$ml$::uuid, 4, $ml$SOC 2 is an audit report$ml$, $ml$A CPA tests a company against up to five criteria. Security is always included; the other four are optional. Type I checks the design; Type II tests how controls work over time.$ml$, $ml$[{"url": "https://cpl.thalesgroup.com/insights/cybersecurity/what-is-soc-2-compliance", "label": "Thales, what is SOC 2 compliance"}]$ml$::jsonb),
