($ml$cb6e3ecf-e348-51fb-aa35-0eaf65ac754d$ml$::uuid, $ml$e11c80be-e6f8-5dbb-bbc1-9b643f2c4e4b$ml$::uuid, 2, $ml$The clock$ml$, $ml$24 hours for an early warning, 48 more for the notification. Then one month for a final report with the root cause.$ml$, $ml$[{"url": "https://wsgr.com/en/insights/nis2-preparing-for-eus-new-cybersecurity-rules.html", "label": "Wilson Sonsini, preparing for the EU's NIS2 rules"}]$ml$::jsonb),
