($ml$dd9bfb6c-f6ad-5488-94ed-cc3384c04b20$ml$::uuid, $ml$e2032d6b-32dc-50a9-86fc-922e2ba7b1c5$ml$::uuid, 4, $ml$Not all MFA is equal$ml$, $ml$Codes and push prompts can still be phished or approved by mistake. Stronger forms resist that.$ml$, $ml$[{"url": "https://arxiv.org/abs/2305.00945", "label": "Microsoft researchers, how effective is MFA"}, {"url": "https://www.whitehouse.gov/wp-content/uploads/2022/01/M-22-09.pdf", "label": "OMB memo M-22-09, federal zero trust strategy"}]$ml$::jsonb),
($ml$1fa6a1fe-4cef-593f-819f-f525b91e5767$ml$::uuid, $ml$e2032d6b-32dc-50a9-86fc-922e2ba7b1c5$ml$::uuid, 5, $ml$Simple controls, big effect$ml$, $ml$MFA removes most account takeover risk. Products that make it painless have a strong case.$ml$, $ml$[{"url": "https://arxiv.org/abs/2305.00945", "label": "Microsoft researchers, how effective is MFA"}]$ml$::jsonb),
