($ml$305508ee-f8a5-508c-9369-cb947deb0d36$ml$::uuid, $ml$8db85b1a-2d8f-55e1-9d1b-f1560da256a0$ml$::uuid, 4, $ml$Not all MFA is equal$ml$, $ml$Codes and push prompts can still be phished or approved by mistake. Stronger forms resist that.$ml$, $ml$[{"url": "https://arxiv.org/abs/2305.00945", "label": "Microsoft researchers, how effective is MFA"}, {"url": "https://www.whitehouse.gov/wp-content/uploads/2022/01/M-22-09.pdf", "label": "OMB memo M-22-09, federal zero trust strategy"}]$ml$::jsonb),
($ml$68302ae1-5112-559a-a969-d49b0e61a965$ml$::uuid, $ml$8db85b1a-2d8f-55e1-9d1b-f1560da256a0$ml$::uuid, 5, $ml$Make MFA effortless$ml$, $ml$MFA works but adds friction. Lower the friction and more people keep it on.$ml$, $ml$[{"url": "https://arxiv.org/abs/2305.00945", "label": "Microsoft researchers, how effective is MFA"}]$ml$::jsonb),
($ml$7f8ab961-9e8f-51d3-aff0-848a3247cc61$ml$::uuid, $ml$8db85b1a-2d8f-55e1-9d1b-f1560da256a0$ml$::uuid, 6, $ml$The rule$ml$, $ml$In cyber, the cheapest controls are often the ones that matter most.$ml$, $ml$[{"url": "https://arxiv.org/abs/2305.00945", "label": "Microsoft researchers, how effective is MFA"}]$ml$::jsonb),
