($ml$2121afd2-f947-58bd-bbe8-d256135f8e35$ml$::uuid, $ml$d109a838-3236-5193-9aae-461c277ab114$ml$::uuid, 4, $ml$Not all MFA is equal$ml$, $ml$Codes and push prompts can still be phished or approved by mistake. Stronger forms resist that.$ml$, $ml$[{"url": "https://arxiv.org/abs/2305.00945", "label": "Microsoft researchers, how effective is MFA"}, {"url": "https://www.whitehouse.gov/wp-content/uploads/2022/01/M-22-09.pdf", "label": "OMB memo M-22-09, federal zero trust strategy"}]$ml$::jsonb),
($ml$8f8d07b5-8d24-518e-aa90-70cd1f76d0e3$ml$::uuid, $ml$d109a838-3236-5193-9aae-461c277ab114$ml$::uuid, 5, $ml$A second step, 99% safer$ml$, $ml$Turning on a second login step blocked about 99 of every 100 account compromises in one study.$ml$, $ml$[{"url": "https://arxiv.org/abs/2305.00945", "label": "Microsoft researchers, how effective is MFA"}]$ml$::jsonb),
($ml$0de3db74-c4e6-590c-bf30-4bc182172a45$ml$::uuid, $ml$d109a838-3236-5193-9aae-461c277ab114$ml$::uuid, 6, $ml$The rule$ml$, $ml$In cyber, the cheapest controls are often the ones that matter most.$ml$, $ml$[{"url": "https://arxiv.org/abs/2305.00945", "label": "Microsoft researchers, how effective is MFA"}]$ml$::jsonb),
($ml$c139f3cb-9341-5832-ba28-131bc24d7cd3$ml$::uuid, $ml$5100f01b-5411-5e5c-a27c-d10551ebd424$ml$::uuid, 1, $ml$Day 23 · The rule$ml$, $ml$A January 2022 White House memo required phishing-resistant MFA for federal staff by the end of fiscal 2024. Memo M-22-09 told agencies to stop supporting login methods that fail to resist phishing, including SMS or voice codes, one-time codes and push notifications, for routine access. It also ordered them to drop password rules requiring special characters and regular rotation.$ml$, $ml$[{"url": "https://www.whitehouse.gov/wp-content/uploads/2022/01/M-22-09.pdf", "label": "OMB memo M-22-09, federal zero trust strategy"}]$ml$::jsonb),
($ml$129e925f-0ce9-563a-9dd1-eb48e26120a1$ml$::uuid, $ml$5100f01b-5411-5e5c-a27c-d10551ebd424$ml$::uuid, 2, $ml$The problem$ml$, $ml$A code can be typed into a fake site as easily as a real one. Phishing-resistant methods check the site, not just the person.$ml$, $ml$[{"url": "https://www.whitehouse.gov/wp-content/uploads/2022/01/M-22-09.pdf", "label": "OMB memo M-22-09, federal zero trust strategy"}]$ml$::jsonb),
($ml$26036f32-a32a-5a52-83e1-e4ab4fb97042$ml$::uuid, $ml$5100f01b-5411-5e5c-a27c-d10551ebd424$ml$::uuid, 3, $ml$The surprise$ml$, $ml$The memo dropped forced password changes and special-character rules. Agencies had one year to remove them.$ml$, $ml$[{"url": "https://www.whitehouse.gov/wp-content/uploads/2022/01/M-22-09.pdf", "label": "OMB memo M-22-09, federal zero trust strategy"}]$ml$::jsonb),
($ml$0aba7eb4-5394-52db-a134-f628208a23a2$ml$::uuid, $ml$5100f01b-5411-5e5c-a27c-d10551ebd424$ml$::uuid, 4, $ml$Staff, contractors and partners$ml$, $ml$Phishing-resistant MFA is required for agency staff, contractors and partners using enterprise-managed identities.$ml$, $ml$[{"url": "https://www.whitehouse.gov/wp-content/uploads/2022/01/M-22-09.pdf", "label": "OMB memo M-22-09, federal zero trust strategy"}]$ml$::jsonb),
($ml$52b8a596-690b-5501-812a-cab45e8692f2$ml$::uuid, $ml$5100f01b-5411-5e5c-a27c-d10551ebd424$ml$::uuid, 5, $ml$Know phishing-resistant MFA$ml$, $ml$Being able to explain why SMS codes fall short shows you know modern identity security.$ml$, $ml$[{"url": "https://www.whitehouse.gov/wp-content/uploads/2022/01/M-22-09.pdf", "label": "OMB memo M-22-09, federal zero trust strategy"}]$ml$::jsonb),
