($ml$37bfc03b-d85a-5e64-a74f-581b02d84ab4$ml$::uuid, $ml$34e48d3b-815d-5ef2-b616-b5e0373fbfa9$ml$::uuid, 4, $ml$Finding all the old encryption$ml$, $ml$Companies must first find every place they use vulnerable encryption before they can replace it.$ml$, $ml$[{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]$ml$::jsonb),
